-- Part 2: Verses for Chapters 1 through 9 (360 Verses)
INSERT INTO public.gita_verses (id, chapter_number, verse_number, verse_order, external_id, sanskrit, transliteration, word_meanings, word_meanings_raw) VALUES
('8908c144-8a4f-5da6-b251-50dff0115c0d'::uuid, 1, 1, 1, 1, 'धृतराष्ट्र उवाच

धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः।

मामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय।।1.1।।', 'dhṛitarāśhtra uvācha
dharma-kṣhetre kuru-kṣhetre samavetā yuyutsavaḥ
māmakāḥ pāṇḍavāśhchaiva kimakurvata sañjaya', '[{"word":"dhṛitarāśhtraḥ uvācha","meaning":"Dhritarashtra said"},{"word":"dharma","meaning":"kṣhetre—the land of dharma"},{"word":"kuru","meaning":"kṣhetre—at Kurukshetra"},{"word":"samavetāḥ","meaning":"having gathered"},{"word":"yuyutsavaḥ","meaning":"desiring to fight"},{"word":"māmakāḥ","meaning":"my sons"},{"word":"pāṇḍavāḥ","meaning":"the sons of Pandu"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"certainly"},{"word":"kim","meaning":"what"},{"word":"akurvata","meaning":"did they do"},{"word":"sañjaya","meaning":"Sanjay"}]'::jsonb, 'dhṛitarāśhtraḥ uvācha—Dhritarashtra said; dharma-kṣhetre—the land of dharma; kuru-kṣhetre—at Kurukshetra; samavetāḥ—having gathered; yuyutsavaḥ—desiring to fight; māmakāḥ—my sons; pāṇḍavāḥ—the sons of Pandu; cha—and; eva—certainly; kim—what; akurvata—did they do; sañjaya—Sanjay'),
('39650053-34a7-522a-9ced-97f638529efc'::uuid, 1, 2, 2, 2, 'सञ्जय उवाच

दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा।

आचार्यमुपसङ्गम्य राजा वचनमब्रवीत्।।1.2।।', 'sañjaya uvācha
dṛiṣhṭvā tu pāṇḍavānīkaṁ vyūḍhaṁ duryodhanastadā
āchāryamupasaṅgamya rājā vachanamabravīt', '[{"word":"sanjayaḥ uvācha","meaning":"Sanjay said"},{"word":"dṛiṣhṭvā","meaning":"on observing"},{"word":"tu","meaning":"but"},{"word":"pāṇḍava","meaning":"anīkam—the Pandava army"},{"word":"vyūḍham","meaning":"standing in a military formation"},{"word":"duryodhanaḥ","meaning":"King Duryodhan"},{"word":"tadā","meaning":"then"},{"word":"āchāryam","meaning":"teacher"},{"word":"upasaṅgamya","meaning":"approached"},{"word":"rājā","meaning":"the king"},{"word":"vachanam","meaning":"words"},{"word":"abravīt","meaning":"spoke"}]'::jsonb, 'sanjayaḥ uvācha—Sanjay said; dṛiṣhṭvā—on observing; tu—but; pāṇḍava-anīkam—the Pandava army; vyūḍham—standing in a military formation; duryodhanaḥ—King Duryodhan; tadā—then; āchāryam—teacher; upasaṅgamya—approached; rājā—the king; vachanam—words; abravīt—spoke'),
('48576bc0-f366-5487-9fed-7a05c6319892'::uuid, 1, 3, 3, 3, 'पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।

व्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता।।1.3।।', 'paśhyaitāṁ pāṇḍu-putrāṇām āchārya mahatīṁ chamūm
vyūḍhāṁ drupada-putreṇa tava śhiṣhyeṇa dhīmatā', '[{"word":"paśhya","meaning":"behold"},{"word":"etām","meaning":"this"},{"word":"pāṇḍu","meaning":"putrāṇām—of the sons of Pandu"},{"word":"āchārya","meaning":"respected teacher"},{"word":"mahatīm","meaning":"mighty"},{"word":"chamūm","meaning":"army"},{"word":"vyūḍhām","meaning":"arrayed in a military formation"},{"word":"drupada","meaning":"putreṇa—son of Drupad, Dhrishtadyumna"},{"word":"tava","meaning":"by your"},{"word":"śhiṣhyeṇa","meaning":"disciple"},{"word":"dhī","meaning":"matā—intelligent"}]'::jsonb, 'paśhya—behold; etām—this; pāṇḍu-putrāṇām—of the sons of Pandu; āchārya—respected teacher; mahatīm—mighty; chamūm—army; vyūḍhām—arrayed in a military formation; drupada-putreṇa—son of Drupad, Dhrishtadyumna; tava—by your; śhiṣhyeṇa—disciple; dhī-matā—intelligent'),
('be79d223-ef7f-5266-affb-9d69c3cdb9ed'::uuid, 1, 4, 4, 4, 'अत्र शूरा महेष्वासा भीमार्जुनसमा युधि।

युयुधानो विराटश्च द्रुपदश्च महारथः।।1.4।।', 'atra śhūrā maheṣhvāsā bhīmārjuna-samā yudhi
yuyudhāno virāṭaśhcha drupadaśhcha mahā-rathaḥ', '[{"word":"atra","meaning":"here"},{"word":"śhūrāḥ","meaning":"powerful warriors"},{"word":"mahā","meaning":"iṣhu-āsāḥ—great bowmen"},{"word":"bhīma","meaning":"arjuna-samāḥ—equal to Bheem and Arjun"},{"word":"yudhi","meaning":"in military prowess"},{"word":"yuyudhānaḥ","meaning":"Yuyudhan"},{"word":"virāṭaḥ","meaning":"Virat"},{"word":"cha","meaning":"and"},{"word":"drupadaḥ","meaning":"Drupad"},{"word":"cha","meaning":"also"},{"word":"mahā","meaning":"rathaḥ—warriors who could single handedly match the strength of ten thousand ordinary warriors"}]'::jsonb, 'atra—here; śhūrāḥ—powerful warriors; mahā-iṣhu-āsāḥ—great bowmen; bhīma-arjuna-samāḥ—equal to Bheem and Arjun; yudhi—in military prowess; yuyudhānaḥ—Yuyudhan; virāṭaḥ—Virat; cha—and; drupadaḥ—Drupad; cha—also; mahā-rathaḥ—warriors who could single handedly match the strength of ten thousand ordinary warriors;'),
('6c0143e3-a069-591b-b363-d4223275d69f'::uuid, 1, 5, 5, 5, 'धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान्।

पुरुजित्कुन्तिभोजश्च शैब्यश्च नरपुङ्गवः।।1.5।।', 'dhṛiṣhṭaketuśhchekitānaḥ kāśhirājaśhcha vīryavān
purujit kuntibhojaśhcha śhaibyaśhcha nara-puṅgavaḥ
yudhāmanyuśhcha vikrānta uttamaujāśhcha vīryavān', '[{"word":"dhṛiṣhṭaketuḥ","meaning":"Dhrishtaketu"},{"word":"chekitānaḥ","meaning":"Chekitan"},{"word":"kāśhirājaḥ","meaning":"Kashiraj"},{"word":"cha","meaning":"and"},{"word":"vīrya","meaning":"vān—heroic"},{"word":"purujit","meaning":"Purujit"},{"word":"kuntibhojaḥ","meaning":"Kuntibhoj"},{"word":"cha","meaning":"and"},{"word":"śhaibyaḥ","meaning":"Shaibya"},{"word":"cha","meaning":"and"},{"word":"nara","meaning":"puṅgavaḥ—best of men"},{"word":"yudhāmanyuḥ","meaning":"Yudhamanyu"},{"word":"cha","meaning":"and"},{"word":"vikrāntaḥ","meaning":"courageous"},{"word":"uttamaujāḥ","meaning":"Uttamauja"},{"word":"cha","meaning":"and"},{"word":"vīrya","meaning":"vān—gallant"}]'::jsonb, 'dhṛiṣhṭaketuḥ—Dhrishtaketu; chekitānaḥ—Chekitan; kāśhirājaḥ—Kashiraj; cha—and; vīrya-vān—heroic; purujit—Purujit; kuntibhojaḥ—Kuntibhoj; cha—and; śhaibyaḥ—Shaibya; cha—and; nara-puṅgavaḥ—best of men; yudhāmanyuḥ—Yudhamanyu; cha—and; vikrāntaḥ—courageous; uttamaujāḥ—Uttamauja; cha—and; vīrya-vān—gallant;'),
('521460fd-2273-5364-b2e1-c888e6f7fa2f'::uuid, 1, 6, 6, 6, 'युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान्।

सौभद्रो द्रौपदेयाश्च सर्व एव महारथाः।।1.6।।', 'saubhadro draupadeyāśhcha sarva eva mahā-rathāḥ', '[{"word":"saubhadraḥ","meaning":"the son of Subhadra"},{"word":"draupadeyāḥ","meaning":"the sons of Draupadi"},{"word":"cha","meaning":"and"},{"word":"sarve","meaning":"all"},{"word":"eva","meaning":"indeed"},{"word":"mahā","meaning":"rathāḥ—warriors who could single handedly match the strength of ten thousand ordinary warriors"}]'::jsonb, 'saubhadraḥ—the son of Subhadra; draupadeyāḥ—the sons of Draupadi; cha—and; sarve—all; eva—indeed; mahā-rathāḥ—warriors who could single handedly match the strength of ten thousand ordinary warriors'),
('fa01897d-be77-5757-a521-f758ae4ff33e'::uuid, 1, 7, 7, 7, 'अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम।

नायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते।।1.7।।', 'asmākaṁ tu viśhiṣhṭā ye tānnibodha dwijottama
nāyakā mama sainyasya sanjñārthaṁ tānbravīmi te', '[{"word":"asmākam","meaning":"ours"},{"word":"tu","meaning":"but"},{"word":"viśhiṣhṭāḥ","meaning":"special"},{"word":"ye","meaning":"who"},{"word":"tān","meaning":"them"},{"word":"nibodha","meaning":"be informed"},{"word":"dwija","meaning":"uttama—best of Brahmnis"},{"word":"nāyakāḥ","meaning":"principal generals"},{"word":"mama","meaning":"our"},{"word":"sainyasya","meaning":"of army"},{"word":"sanjñā","meaning":"artham—for information"},{"word":"tān","meaning":"them"},{"word":"bravīmi","meaning":"I recount"},{"word":"te","meaning":"unto you"}]'::jsonb, 'asmākam—ours; tu—but; viśhiṣhṭāḥ—special; ye—who; tān—them; nibodha—be informed; dwija-uttama—best of Brahmnis; nāyakāḥ—principal generals; mama—our; sainyasya—of army; sanjñā-artham—for information; tān—them; bravīmi—I recount; te—unto you'),
('bed96014-9b78-5203-a88b-31adcd509694'::uuid, 1, 8, 8, 8, 'भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः।

अश्वत्थामा विकर्णश्च सौमदत्तिस्तथैव च।।1.8।।', 'bhavānbhīṣhmaśhcha karṇaśhcha kṛipaśhcha samitiñjayaḥ
aśhvatthāmā vikarṇaśhcha saumadattis tathaiva cha', '[{"word":"bhavān","meaning":"yourself"},{"word":"bhīṣhmaḥ","meaning":"Bheeshma"},{"word":"cha","meaning":"and"},{"word":"karṇaḥ","meaning":"Karna"},{"word":"cha","meaning":"and"},{"word":"kṛipaḥ","meaning":"Kripa"},{"word":"cha","meaning":"and"},{"word":"samitim","meaning":"jayaḥ—victorious in battle"},{"word":"aśhvatthāmā","meaning":"Ashvatthama"},{"word":"vikarṇaḥ","meaning":"Vikarna"},{"word":"cha","meaning":"and"},{"word":"saumadattiḥ","meaning":"Bhurishrava"},{"word":"tathā","meaning":"thus"},{"word":"eva","meaning":"even"},{"word":"cha","meaning":"also"}]'::jsonb, 'bhavān—yourself; bhīṣhmaḥ—Bheeshma; cha—and; karṇaḥ—Karna; cha—and; kṛipaḥ—Kripa; cha—and; samitim-jayaḥ—victorious in battle; aśhvatthāmā—Ashvatthama; vikarṇaḥ—Vikarna; cha—and; saumadattiḥ—Bhurishrava; tathā—thus; eva—even; cha—also'),
('54ae0136-fbd5-55cf-be65-d290f409c47e'::uuid, 1, 9, 9, 9, 'अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः।

नानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः।।1.9।।', 'anye cha bahavaḥ śhūrā madarthe tyaktajīvitāḥ
nānā-śhastra-praharaṇāḥ sarve yuddha-viśhāradāḥ', '[{"word":"anye","meaning":"others"},{"word":"cha","meaning":"also"},{"word":"bahavaḥ","meaning":"many"},{"word":"śhūrāḥ","meaning":"heroic warriors"},{"word":"mat","meaning":"arthe—for my sake"},{"word":"tyakta","meaning":"jīvitāḥ—prepared to lay down their lives"},{"word":"nānā","meaning":"śhastra-praharaṇāḥ—equipped with various kinds of weapons"},{"word":"sarve","meaning":"all"},{"word":"yuddha","meaning":"viśhāradāḥ—skilled in the art of warfare"}]'::jsonb, 'anye—others; cha—also; bahavaḥ—many; śhūrāḥ—heroic warriors; mat-arthe—for my sake; tyakta-jīvitāḥ—prepared to lay down their lives; nānā-śhastra-praharaṇāḥ—equipped with various kinds of weapons; sarve—all; yuddha-viśhāradāḥ—skilled in the art of warfare'),
('1addcdad-fc61-53ce-9566-fe7967dc78ac'::uuid, 1, 10, 10, 10, 'अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्।

पर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम्।।1.10।।', 'aparyāptaṁ tadasmākaṁ balaṁ bhīṣhmābhirakṣhitam
paryāptaṁ tvidameteṣhāṁ balaṁ bhīmābhirakṣhitam', '[{"word":"aparyāptam","meaning":"unlimited"},{"word":"tat","meaning":"that"},{"word":"asmākam","meaning":"ours"},{"word":"balam","meaning":"strength"},{"word":"bhīṣhma","meaning":"by Grandsire Bheeshma"},{"word":"abhirakṣhitam","meaning":"safely marshalled"},{"word":"paryāptam","meaning":"limited"},{"word":"tu","meaning":"but"},{"word":"idam","meaning":"this"},{"word":"eteṣhām","meaning":"their"},{"word":"balam","meaning":"strength"},{"word":"bhīma","meaning":"Bheem"},{"word":"abhirakṣhitam","meaning":"carefully marshalled"}]'::jsonb, 'aparyāptam—unlimited; tat—that; asmākam—ours; balam—strength; bhīṣhma—by Grandsire Bheeshma; abhirakṣhitam—safely marshalled; paryāptam—limited; tu—but; idam—this; eteṣhām—their; balam—strength; bhīma—Bheem; abhirakṣhitam—carefully marshalled'),
('9463be70-e124-5030-a110-47b1c54f3638'::uuid, 1, 11, 11, 11, 'अयनेषु च सर्वेषु यथाभागमवस्थिताः।

भीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि।।1.11।।', 'ayaneṣhu cha sarveṣhu yathā-bhāgamavasthitāḥ
bhīṣhmamevābhirakṣhantu bhavantaḥ sarva eva hi', '[{"word":"ayaneṣhu","meaning":"at the strategic points"},{"word":"cha","meaning":"also"},{"word":"sarveṣhu","meaning":"all"},{"word":"yathā","meaning":"bhāgam—in respective position"},{"word":"avasthitāḥ","meaning":"situated"},{"word":"bhīṣhmam","meaning":"to Grandsire Bheeshma"},{"word":"eva","meaning":"only"},{"word":"abhirakṣhantu","meaning":"defend"},{"word":"bhavantaḥ","meaning":"you"},{"word":"sarve","meaning":"all"},{"word":"eva hi","meaning":"even as"}]'::jsonb, 'ayaneṣhu—at the strategic points; cha—also; sarveṣhu—all; yathā-bhāgam—in respective position; avasthitāḥ—situated; bhīṣhmam—to Grandsire Bheeshma; eva—only; abhirakṣhantu—defend; bhavantaḥ—you; sarve—all; eva hi—even as'),
('cb447a08-1645-5d32-80cb-d298aa07d91a'::uuid, 1, 12, 12, 12, 'तस्य संजनयन्हर्षं कुरुवृद्धः पितामहः।

सिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान्।।1.12।।', 'tasya sañjanayan harṣhaṁ kuru-vṛiddhaḥ pitāmahaḥ
siṁha-nādaṁ vinadyochchaiḥ śhaṅkhaṁ dadhmau pratāpavān', '[{"word":"tasya","meaning":"his"},{"word":"sañjanayan","meaning":"causing"},{"word":"harṣham","meaning":"joy"},{"word":"kuru","meaning":"vṛiddhaḥ—the grand old man of the Kuru dynasty (Bheeshma)"},{"word":"pitāmahaḥ","meaning":"grandfather"},{"word":"sinha","meaning":"nādam—lion’s roar"},{"word":"vinadya","meaning":"sounding"},{"word":"uchchaiḥ","meaning":"very loudly"},{"word":"śhaṅkham","meaning":"conch shell"},{"word":"dadhmau","meaning":"blew"},{"word":"pratāpa","meaning":"vān—the glorious"}]'::jsonb, 'tasya—his; sañjanayan—causing; harṣham—joy; kuru-vṛiddhaḥ—the grand old man of the Kuru dynasty (Bheeshma); pitāmahaḥ—grandfather; sinha-nādam—lion’s roar; vinadya—sounding; uchchaiḥ—very loudly; śhaṅkham—conch shell; dadhmau—blew; pratāpa-vān—the glorious'),
('0acbd4d6-a413-517e-8017-5d8d14ed599a'::uuid, 1, 13, 13, 13, 'ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः।

सहसैवाभ्यहन्यन्त स शब्दस्तुमुलोऽभवत्।।1.13।।', 'tataḥ śhaṅkhāśhcha bheryaśhcha paṇavānaka-gomukhāḥ
sahasaivābhyahanyanta sa śhabdastumulo ’bhavat', '[{"word":"tataḥ","meaning":"thereafter"},{"word":"śhaṅkhāḥ","meaning":"conches"},{"word":"cha","meaning":"and"},{"word":"bheryaḥ","meaning":"bugles"},{"word":"cha","meaning":"and"},{"word":"paṇava","meaning":"ānaka—drums and kettledrums"},{"word":"go","meaning":"mukhāḥ—trumpets"},{"word":"sahasā","meaning":"suddenly"},{"word":"eva","meaning":"indeed"},{"word":"abhyahanyanta","meaning":"blared forth"},{"word":"saḥ","meaning":"that"},{"word":"śhabdaḥ","meaning":"sound"},{"word":"tumulaḥ","meaning":"overwhelming"},{"word":"abhavat","meaning":"was"}]'::jsonb, 'tataḥ—thereafter; śhaṅkhāḥ—conches; cha—and; bheryaḥ—bugles; cha—and; paṇava-ānaka—drums and kettledrums; go-mukhāḥ—trumpets; sahasā—suddenly; eva—indeed; abhyahanyanta—blared forth; saḥ—that; śhabdaḥ—sound; tumulaḥ—overwhelming; abhavat—was'),
('81751ab9-f902-5dee-bad9-6267d9e1c66f'::uuid, 1, 14, 14, 14, 'ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ।

माधवः पाण्डवश्चैव दिव्यौ शङ्खौ प्रदध्मतुः।।1.14।।', 'tataḥ śhvetairhayairyukte mahati syandane sthitau
mādhavaḥ pāṇḍavaśhchaiva divyau śhaṅkhau pradadhmatuḥ', '[{"word":"tataḥ","meaning":"then"},{"word":"śhvetaiḥ","meaning":"by white"},{"word":"hayaiḥ","meaning":"horses"},{"word":"yukte","meaning":"yoked"},{"word":"mahati","meaning":"glorious"},{"word":"syandane","meaning":"chariot"},{"word":"sthitau","meaning":"seated"},{"word":"mādhavaḥ","meaning":"Shree Krishna, the husband of the goddess of fortune, Lakshmi"},{"word":"pāṇḍavaḥ","meaning":"Arjun"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"also"},{"word":"divyau","meaning":"Divine"},{"word":"śhaṅkhau","meaning":"conch shells"},{"word":"pradadhmatuḥ","meaning":"blew"}]'::jsonb, 'tataḥ—then; śhvetaiḥ—by white; hayaiḥ—horses; yukte—yoked; mahati—glorious; syandane—chariot; sthitau—seated; mādhavaḥ—Shree Krishna, the husband of the goddess of fortune, Lakshmi; pāṇḍavaḥ—Arjun; cha—and; eva—also; divyau—Divine; śhaṅkhau—conch shells; pradadhmatuḥ—blew'),
('a20e47f4-e0c2-582d-841c-b9addbae304b'::uuid, 1, 15, 15, 15, 'पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः।

पौण्ड्रं दध्मौ महाशङ्खं भीमकर्मा वृकोदरः।।1.15।।', 'pāñchajanyaṁ hṛiṣhīkeśho devadattaṁ dhanañjayaḥ
pauṇḍraṁ dadhmau mahā-śhaṅkhaṁ bhīma-karmā vṛikodaraḥ', '[{"word":"pāñchajanyam","meaning":"the conch shell named Panchajanya"},{"word":"hṛiṣhīka","meaning":"īśhaḥ—Shree Krishna, the Lord of the mind and senses"},{"word":"devadattam","meaning":"the conch shell named Devadutta"},{"word":"dhanam","meaning":"jayaḥ—Arjun, the winner of wealth"},{"word":"pauṇḍram","meaning":"the conch named Paundra"},{"word":"dadhmau","meaning":"blew"},{"word":"mahā","meaning":"śhaṅkham—mighty conch"},{"word":"bhīma","meaning":"karmā—one who performs herculean tasks"},{"word":"vṛika","meaning":"udaraḥ—Bheem, the voracious eater"}]'::jsonb, 'pāñchajanyam—the conch shell named Panchajanya; hṛiṣhīka-īśhaḥ—Shree Krishna, the Lord of the mind and senses; devadattam—the conch shell named Devadutta; dhanam-jayaḥ—Arjun, the winner of wealth; pauṇḍram—the conch named Paundra; dadhmau—blew; mahā-śhaṅkham—mighty conch; bhīma-karmā—one who performs herculean tasks; vṛika-udaraḥ—Bheem, the voracious eater'),
('f85c985e-f0da-5880-8f00-998c8b738624'::uuid, 1, 16, 16, 16, 'अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः।

नकुलः सहदेवश्च सुघोषमणिपुष्पकौ।।1.16।।', 'anantavijayaṁ rājā kuntī-putro yudhiṣhṭhiraḥ
