('0dacaed8-ac46-54ac-96b3-2419fa05dac9'::uuid, 1, 21, 21, 21, 'अर्जुन उवाच

हृषीकेशं तदा वाक्यमिदमाह महीपते।

सेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत।।1.21।।', 'arjuna uvācha
senayor ubhayor madhye rathaṁ sthāpaya me ’chyuta', '[{"word":"arjunaḥ uvācha","meaning":"Arjun said"},{"word":"senayoḥ","meaning":"armies"},{"word":"ubhayoḥ","meaning":"both"},{"word":"madhye","meaning":"in the middle"},{"word":"ratham","meaning":"chariot"},{"word":"sthāpaya","meaning":"place"},{"word":"me","meaning":"my"},{"word":"achyuta","meaning":"Shree Krishna, the infallible One"}]'::jsonb, 'arjunaḥ uvācha—Arjun said; senayoḥ—armies; ubhayoḥ—both; madhye—in the middle; ratham—chariot; sthāpaya—place; me—my; achyuta—Shree Krishna, the infallible One;'),
('deaf76ac-eb32-5174-a19f-0452e6b8a6e0'::uuid, 1, 22, 22, 22, 'यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान्।

कैर्मया सह योद्धव्यमस्मिन्रणसमुद्यमे।।1.22।।', 'yāvadetān nirīkṣhe ’haṁ yoddhu-kāmān avasthitān
kairmayā saha yoddhavyam asmin raṇa-samudyame', '[{"word":"yāvat","meaning":"as many as"},{"word":"etān","meaning":"these"},{"word":"nirīkṣhe","meaning":"look"},{"word":"aham","meaning":"I"},{"word":"yoddhu","meaning":"kāmān—for the battle"},{"word":"avasthitān","meaning":"arrayed"},{"word":"kaiḥ","meaning":"with whom"},{"word":"mayā","meaning":"by me"},{"word":"saha","meaning":"together"},{"word":"yoddhavyam","meaning":"must fight"},{"word":"asmin","meaning":"in this"},{"word":"raṇa","meaning":"samudyame—great combat"}]'::jsonb, 'yāvat—as many as; etān—these; nirīkṣhe—look; aham—I; yoddhu-kāmān—for the battle; avasthitān—arrayed; kaiḥ—with whom; mayā—by me; saha—together; yoddhavyam—must fight; asmin—in this; raṇa-samudyame—great combat'),
('4acb1945-35fe-5330-8199-ecb8441a19b5'::uuid, 1, 23, 23, 23, 'योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः।

धार्तराष्ट्रस्य दुर्बुद्धेर्युद्धे प्रियचिकीर्षवः।।1.23।।', 'yotsyamānān avekṣhe ’haṁ ya ete ’tra samāgatāḥ
