('0e377d0d-745c-5f39-90fd-c3d9eaf95235'::uuid, 1, 27, 27, 27, 'श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि।

तान्समीक्ष्य स कौन्तेयः सर्वान्बन्धूनवस्थितान्।।1.27।।', 'tān samīkṣhya sa kaunteyaḥ sarvān bandhūn avasthitān
kṛipayā parayāviṣhṭo viṣhīdann idam abravīt', '[{"word":"tān","meaning":"these"},{"word":"samīkṣhya","meaning":"on seeing"},{"word":"saḥ","meaning":"they"},{"word":"kaunteyaḥ","meaning":"Arjun, the son of Kunti"},{"word":"sarvān","meaning":"all"},{"word":"bandhūn","meaning":"relatives"},{"word":"avasthitān","meaning":"present"},{"word":"kṛipayā","meaning":"by compassion"},{"word":"parayā","meaning":"great"},{"word":"āviṣhṭaḥ","meaning":"overwhelmed"},{"word":"viṣhīdan","meaning":"deep sorrow"},{"word":"idam","meaning":"this"},{"word":"abravīt","meaning":"spoke"}]'::jsonb, 'tān—these; samīkṣhya—on seeing; saḥ—they; kaunteyaḥ—Arjun, the son of Kunti; sarvān—all; bandhūn—relatives; avasthitān—present; kṛipayā—by compassion; parayā—great; āviṣhṭaḥ—overwhelmed; viṣhīdan—deep sorrow; idam—this; abravīt—spoke'),
('c2f2bbdd-1a17-54eb-a64c-6d12016b7739'::uuid, 1, 28, 28, 28, 'अर्जुन उवाच

कृपया परयाऽऽविष्टो विषीदन्निदमब्रवीत्।

दृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम्।।1.28।।', 'arjuna uvācha
dṛiṣhṭvemaṁ sva-janaṁ kṛiṣhṇa yuyutsuṁ samupasthitam', '[{"word":"arjunaḥ uvācha","meaning":"Arjun said"},{"word":"dṛiṣhṭvā","meaning":"on seeing"},{"word":"imam","meaning":"these"},{"word":"sva","meaning":"janam—kinsmen"},{"word":"kṛiṣhṇa","meaning":"Krishna"},{"word":"yuyutsum","meaning":"eager to fight"},{"word":"samupasthitam","meaning":"present"}]'::jsonb, 'arjunaḥ uvācha—Arjun said; dṛiṣhṭvā—on seeing; imam—these; sva-janam—kinsmen; kṛiṣhṇa—Krishna; yuyutsum—eager to fight; samupasthitam—present;'),
('84b2b286-799b-503b-99ff-fcd3bf2554a8'::uuid, 1, 29, 29, 29, 'सीदन्ति मम गात्राणि मुखं च परिशुष्यति।

वेपथुश्च शरीरे मे रोमहर्षश्च जायते।।1.29।।', 'sīdanti mama gātrāṇi mukhaṁ cha pariśhuṣhyati
vepathuśh cha śharīre me roma-harṣhaśh cha jāyate', '[{"word":"sīdanti","meaning":"quivering"},{"word":"mama","meaning":"my"},{"word":"gātrāṇi","meaning":"limbs"},{"word":"mukham","meaning":"mouth"},{"word":"cha","meaning":"and"},{"word":"pariśhuṣhyati","meaning":"is drying up vepathuḥ—shuddering"},{"word":"cha","meaning":"and"},{"word":"śharīre","meaning":"on the body"},{"word":"me","meaning":"my"},{"word":"roma","meaning":"harṣhaḥ—standing of bodily hair on end"},{"word":"cha","meaning":"also"},{"word":"jāyate","meaning":"is happening"}]'::jsonb, 'sīdanti—quivering; mama—my; gātrāṇi—limbs; mukham—mouth; cha—and; pariśhuṣhyati—is drying up
vepathuḥ—shuddering; cha—and; śharīre—on the body; me—my; roma-harṣhaḥ—standing of bodily hair on end; cha—also; jāyate—is happening;'),
('dfc1e8d7-2475-5b28-8419-eaded33d850a'::uuid, 1, 30, 30, 30, 'गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते।

न च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः।।1.30।।', 'gāṇḍīvaṁ sraṁsate hastāt tvak chaiva paridahyate
na cha śhaknomy avasthātuṁ bhramatīva cha me manaḥ', '[{"word":"gāṇḍīvam","meaning":"Arjun’s bow"},{"word":"sraṁsate","meaning":"is slipping"},{"word":"hastāt","meaning":"from (my) hand"},{"word":"tvak","meaning":"skin"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"indeed"},{"word":"paridahyate","meaning":"is burning all over"},{"word":"na","meaning":"not"},{"word":"cha","meaning":"and"},{"word":"śhaknomi","meaning":"am able"},{"word":"avasthātum","meaning":"remain steady"},{"word":"bhramati iva","meaning":"whirling like"},{"word":"cha","meaning":"and"},{"word":"me","meaning":"my"},{"word":"manaḥ","meaning":"mind"}]'::jsonb, 'gāṇḍīvam—Arjun’s bow; sraṁsate—is slipping; hastāt—from (my) hand; tvak—skin; cha—and; eva—indeed; paridahyate—is burning all over; na—not; cha—and; śhaknomi—am able; avasthātum—remain steady; bhramati iva—whirling like; cha—and; me—my; manaḥ—mind;'),
('e4a9e229-f38b-5f05-90f3-08a9771f13cf'::uuid, 1, 31, 31, 31, 'निमित्तानि च पश्यामि विपरीतानि केशव।

न च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे।।1.31।।', 'nimittāni cha paśhyāmi viparītāni keśhava
na cha śhreyo ’nupaśhyāmi hatvā sva-janam āhave', '[{"word":"nimittāni","meaning":"omens"},{"word":"cha","meaning":"and"},{"word":"paśhyāmi","meaning":"I see"},{"word":"viparītāni","meaning":"misfortune"},{"word":"keśhava","meaning":"Shree Krishna, killer of the Keshi demon"},{"word":"na","meaning":"not"},{"word":"cha","meaning":"also"},{"word":"śhreyaḥ","meaning":"good"},{"word":"anupaśhyāmi","meaning":"I foresee"},{"word":"hatvā","meaning":"from killing"},{"word":"sva","meaning":"janam—kinsmen"},{"word":"āhave","meaning":"in battle"}]'::jsonb, 'nimittāni—omens; cha—and; paśhyāmi—I see; viparītāni—misfortune; keśhava—Shree Krishna, killer of the Keshi demon; na—not; cha—also; śhreyaḥ—good; anupaśhyāmi—I foresee; hatvā—from killing; sva-janam—kinsmen; āhave—in battle'),
('08511b51-a3d1-531a-a59c-78284db5da1c'::uuid, 1, 32, 32, 32, 'न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च।

किं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा।।1.32।।', 'na kāṅkṣhe vijayaṁ kṛiṣhṇa na cha rājyaṁ sukhāni cha
kiṁ no rājyena govinda kiṁ bhogair jīvitena vā', '[{"word":"na","meaning":"nor"},{"word":"kāṅkṣhe","meaning":"do I desire"},{"word":"vijayam","meaning":"victory"},{"word":"kṛiṣhṇa","meaning":"Krishna"},{"word":"na","meaning":"nor"},{"word":"cha","meaning":"as well"},{"word":"rājyam","meaning":"kingdom"},{"word":"sukhāni","meaning":"happiness"},{"word":"cha","meaning":"also"},{"word":"kim","meaning":"what"},{"word":"naḥ","meaning":"to us"},{"word":"rājyena","meaning":"by kingdom"},{"word":"govinda","meaning":"Krishna, he who gives pleasure to the senses, he who is fond of cows"},{"word":"kim","meaning":"what?"},{"word":"bhogaiḥ","meaning":"pleasures"},{"word":"jīvitena","meaning":"life"},{"word":"vā","meaning":"or"}]'::jsonb, 'na—nor; kāṅkṣhe—do I desire; vijayam—victory; kṛiṣhṇa—Krishna; na—nor; cha—as well; rājyam—kingdom; sukhāni—happiness; cha—also; kim—what; naḥ—to us; rājyena—by kingdom; govinda—Krishna, he who gives pleasure to the senses, he who is fond of cows; kim—what?; bhogaiḥ—pleasures; jīvitena—life; vā—or;'),
('15ccce4b-d3fd-5030-a9f9-7453f30bb2c7'::uuid, 1, 33, 33, 33, 'येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च।

त इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च।।1.33।।', 'yeṣhām arthe kāṅkṣhitaṁ no rājyaṁ bhogāḥ sukhāni cha
ta ime ’vasthitā yuddhe prāṇāṁs tyaktvā dhanāni cha', '[{"word":"yeṣhām","meaning":"for whose"},{"word":"arthe","meaning":"sake"},{"word":"kāṅkṣhitam","meaning":"coveted for"},{"word":"naḥ","meaning":"by us"},{"word":"rājyam","meaning":"kingdom"},{"word":"bhogāḥ","meaning":"pleasures"},{"word":"sukhāni","meaning":"happiness"},{"word":"cha","meaning":"also"},{"word":"te","meaning":"they"},{"word":"ime","meaning":"these"},{"word":"avasthitāḥ","meaning":"situated"},{"word":"yuddhe","meaning":"for battle"},{"word":"prāṇān","meaning":"lives"},{"word":"tyaktvā","meaning":"giving up"},{"word":"dhanāni","meaning":"wealth"},{"word":"cha","meaning":"also"}]'::jsonb, 'yeṣhām—for whose; arthe—sake; kāṅkṣhitam—coveted for; naḥ—by us; rājyam—kingdom; bhogāḥ—pleasures; sukhāni—happiness; cha—also; te—they; ime—these; avasthitāḥ—situated; yuddhe—for battle; prāṇān—lives; tyaktvā—giving up; dhanāni—wealth; cha—also'),
('05dc2578-7055-5593-aaae-281f754b7ead'::uuid, 1, 34, 34, 34, 'आचार्याः पितरः पुत्रास्तथैव च पितामहाः।

मातुलाः श्चशुराः पौत्राः श्यालाः सम्बन्धिनस्तथा।।1.34।।', 'āchāryāḥ pitaraḥ putrās tathaiva cha pitāmahāḥ
mātulāḥ śhvaśhurāḥ pautrāḥ śhyālāḥ sambandhinas tathā', '[{"word":"āchāryāḥ","meaning":"teachers"},{"word":"pitaraḥ","meaning":"fathers"},{"word":"putrāḥ","meaning":"sons"},{"word":"tathā","meaning":"as well"},{"word":"eva","meaning":"indeed"},{"word":"cha","meaning":"also"},{"word":"pitāmahāḥ","meaning":"grandfathers"},{"word":"mātulāḥ","meaning":"maternal uncles"},{"word":"śhvaśhurāḥ","meaning":"fathers-in-law"},{"word":"pautrāḥ","meaning":"grandsons"},{"word":"śhyālāḥ","meaning":"brothers-in-law"},{"word":"sambandhinaḥ","meaning":"kinsmen"},{"word":"tathā","meaning":"as well"}]'::jsonb, 'āchāryāḥ—teachers; pitaraḥ—fathers; putrāḥ—sons; tathā—as well; eva—indeed; cha—also; pitāmahāḥ—grandfathers; mātulāḥ—maternal uncles; śhvaśhurāḥ—fathers-in-law; pautrāḥ—grandsons; śhyālāḥ—brothers-in-law; sambandhinaḥ—kinsmen; tathā—as well;'),
('95f96233-748b-54e1-85c9-da49c51dc0ad'::uuid, 1, 35, 35, 35, 'एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन।

अपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते।।1.35।।', 'etān na hantum ichchhāmi ghnato ’pi madhusūdana
api trailokya-rājyasya hetoḥ kiṁ nu mahī-kṛite', '[{"word":"etān","meaning":"these"},{"word":"na","meaning":"not"},{"word":"hantum","meaning":"to slay"},{"word":"ichchhāmi","meaning":"I wish"},{"word":"ghnataḥ","meaning":"killed"},{"word":"api","meaning":"even though"},{"word":"madhusūdana","meaning":"Shree Krishna, killer of the demon Madhu"},{"word":"api","meaning":"even though"},{"word":"trai","meaning":"lokya-rājyasya—dominion over three worlds"},{"word":"hetoḥ","meaning":"for the sake of"},{"word":"kim nu","meaning":"what to speak of"},{"word":"mahī","meaning":"kṛite—for the earth"}]'::jsonb, 'etān—these; na—not; hantum—to slay; ichchhāmi—I wish; ghnataḥ—killed; api—even though; madhusūdana—Shree Krishna, killer of the demon Madhu; api—even though; trai-lokya-rājyasya—dominion over three worlds; hetoḥ—for the sake of; kim nu—what to speak of; mahī-kṛite—for the earth'),
('19bcf343-fe9f-5d8b-9345-ac87f32830b7'::uuid, 1, 36, 36, 36, 'निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन।

पापमेवाश्रयेदस्मान्हत्वैतानाततायिनः।।1.36।।', 'nihatya dhārtarāṣhṭrān naḥ kā prītiḥ syāj janārdana
pāpam evāśhrayed asmān hatvaitān ātatāyinaḥ', '[{"word":"nihatya","meaning":"by killing"},{"word":"dhārtarāṣhṭrān","meaning":"the sons of Dhritarashtra"},{"word":"naḥ","meaning":"our"},{"word":"kā","meaning":"what"},{"word":"prītiḥ","meaning":"pleasure"},{"word":"syāt","meaning":"will there be"},{"word":"janārdana","meaning":"he who looks after the public, Shree Krishna"},{"word":"pāpam","meaning":"vices"},{"word":"eva","meaning":"certainly"},{"word":"āśhrayet","meaning":"must come upon"},{"word":"asmān","meaning":"us"},{"word":"hatvā","meaning":"by killing"},{"word":"etān","meaning":"all these"},{"word":"ātatāyinaḥ","meaning":"aggressors"}]'::jsonb, 'nihatya—by killing; dhārtarāṣhṭrān—the sons of Dhritarashtra; naḥ—our; kā—what; prītiḥ—pleasure; syāt—will there be; janārdana—he who looks after the public, Shree Krishna; pāpam—vices; eva—certainly; āśhrayet—must come upon; asmān—us; hatvā—by killing; etān—all these; ātatāyinaḥ—aggressors;'),
('034ac013-6f5d-58d7-bc33-0f726dd77f58'::uuid, 1, 37, 37, 37, 'तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान्।

स्वजनं हि कथं हत्वा सुखिनः स्याम माधव।।1.37।।', 'tasmān nārhā vayaṁ hantuṁ dhārtarāṣhṭrān sa-bāndhavān 
sva-janaṁ hi kathaṁ hatvā sukhinaḥ syāma mādhava', '[{"word":"tasmāt","meaning":"hence"},{"word":"na","meaning":"never"},{"word":"arhāḥ","meaning":"behoove"},{"word":"vayam","meaning":"we"},{"word":"hantum","meaning":"to kill"},{"word":"dhārtarāṣhṭrān","meaning":"the sons of Dhritarashtra"},{"word":"sva","meaning":"bāndhavān—along with friends"},{"word":"sva","meaning":"janam—kinsmen"},{"word":"hi","meaning":"certainly"},{"word":"katham","meaning":"how"},{"word":"hatvā","meaning":"by killing"},{"word":"sukhinaḥ","meaning":"happy"},{"word":"syāma","meaning":"will we become"},{"word":"mādhava","meaning":"Shree Krishna, the husband of Yogmaya"}]'::jsonb, 'tasmāt—hence; na—never; arhāḥ—behoove; vayam—we; hantum—to kill; dhārtarāṣhṭrān—the sons of Dhritarashtra; sva-bāndhavān—along with friends; sva-janam—kinsmen; hi—certainly; katham—how; hatvā—by killing; sukhinaḥ—happy; syāma—will we become; mādhava—Shree Krishna, the husband of Yogmaya'),
('767aba6c-fd8e-5d01-929a-c6b29b44164e'::uuid, 1, 38, 38, 38, 'यद्यप्येते न पश्यन्ति लोभोपहतचेतसः।

कुलक्षयकृतं दोषं मित्रद्रोहे च पातकम्।।1.38।।', 'yady apy ete na paśhyanti lobhopahata-chetasaḥ
kula-kṣhaya-kṛitaṁ doṣhaṁ mitra-drohe cha pātakam', '[{"word":"yadi api","meaning":"even though"},{"word":"ete","meaning":"they"},{"word":"na","meaning":"not"},{"word":"paśhyanti","meaning":"see"},{"word":"lobha","meaning":"greed"},{"word":"upahata","meaning":"overpowered"},{"word":"chetasaḥ","meaning":"thoughts"},{"word":"kula","meaning":"kṣhaya-kṛitam—in annihilating their relatives"},{"word":"doṣham","meaning":"fault"},{"word":"mitra","meaning":"drohe—to wreak treachery upon friends"},{"word":"cha","meaning":"and"},{"word":"pātakam","meaning":"sin"}]'::jsonb, 'yadi api—even though; ete—they; na—not; paśhyanti—see; lobha—greed; upahata—overpowered; chetasaḥ—thoughts; kula-kṣhaya-kṛitam—in annihilating their relatives; doṣham—fault; mitra-drohe—to wreak treachery upon friends; cha—and; pātakam—sin;'),
('70e1c57c-7e35-5802-a24b-29af36a87d2c'::uuid, 1, 39, 39, 39, 'कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम्।

कुलक्षयकृतं दोषं प्रपश्यद्भिर्जनार्दन।।1.39।।', 'kathaṁ na jñeyam asmābhiḥ pāpād asmān nivartitum
kula-kṣhaya-kṛitaṁ doṣhaṁ prapaśhyadbhir janārdana', '[{"word":"katham","meaning":"why"},{"word":"na","meaning":"not"},{"word":"jñeyam","meaning":"should be known"},{"word":"asmābhiḥ","meaning":"we"},{"word":"pāpāt","meaning":"from sin"},{"word":"asmāt","meaning":"these"},{"word":"nivartitum","meaning":"to turn away"},{"word":"kula","meaning":"kṣhaya—killing the kindered"},{"word":"kṛitam","meaning":"done"},{"word":"doṣham","meaning":"crime"},{"word":"prapaśhyadbhiḥ","meaning":"who can see"},{"word":"janārdana","meaning":"he who looks after the public, Shree Krishna"}]'::jsonb, 'katham—why; na—not; jñeyam—should be known; asmābhiḥ—we; pāpāt—from sin; asmāt—these; nivartitum—to turn away; kula-kṣhaya—killing the kindered; kṛitam—done; doṣham—crime; prapaśhyadbhiḥ—who can see; janārdana—he who looks after the public, Shree Krishna'),
('37083537-b98a-53eb-ae1d-6417c2b978ae'::uuid, 1, 40, 40, 40, 'कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः।

धर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत।।1.40।।', 'kula-kṣhaye praṇaśhyanti kula-dharmāḥ sanātanāḥ
dharme naṣhṭe kulaṁ kṛitsnam adharmo ’bhibhavaty uta', '[{"word":"kula","meaning":"kṣhaye—in the destruction of a dynasty"},{"word":"praṇaśhyanti","meaning":"are vanquished"},{"word":"kula","meaning":"dharmāḥ—family traditions"},{"word":"sanātanāḥ","meaning":"eternal"},{"word":"dharme","meaning":"religion"},{"word":"naṣhṭe","meaning":"is destroyed"},{"word":"kulam","meaning":"family"},{"word":"kṛitsnam","meaning":"the whole"},{"word":"adharmaḥ","meaning":"irreligion"},{"word":"abhibhavati","meaning":"overcome"},{"word":"uta","meaning":"indeed"}]'::jsonb, 'kula-kṣhaye—in the destruction of a dynasty; praṇaśhyanti—are vanquished; kula-dharmāḥ—family traditions; sanātanāḥ—eternal; dharme—religion; naṣhṭe—is destroyed; kulam—family; kṛitsnam—the whole; adharmaḥ—irreligion; abhibhavati—overcome; uta—indeed'),
('4d3b7f28-2042-59e2-bef8-7308ace03d9a'::uuid, 1, 41, 41, 41, 'अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः।

स्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः।।1.41।।', 'adharmābhibhavāt kṛiṣhṇa praduṣhyanti kula-striyaḥ
