('c35b1179-bfe6-595d-aa16-96b82d818384'::uuid, 1, 42, 42, 42, 'सङ्करो नरकायैव कुलघ्नानां कुलस्य च।

पतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः।।1.42।।', 'saṅkaro narakāyaiva kula-ghnānāṁ kulasya cha
patanti pitaro hy eṣhāṁ lupta-piṇḍodaka-kriyāḥ', '[{"word":"saṅkaraḥ","meaning":"unwanted children"},{"word":"narakāya","meaning":"hellish"},{"word":"eva","meaning":"indeed"},{"word":"kula","meaning":"ghnānām—for those who destroy the family"},{"word":"kulasya","meaning":"of the family"},{"word":"cha","meaning":"also"},{"word":"patanti","meaning":"fall"},{"word":"pitaraḥ","meaning":"ancestors"},{"word":"hi","meaning":"verily"},{"word":"eṣhām","meaning":"their"},{"word":"lupta","meaning":"deprived of"},{"word":"piṇḍodaka","meaning":"kriyāḥ—performances of sacrificial offerings"}]'::jsonb, 'saṅkaraḥ—unwanted children; narakāya—hellish; eva—indeed; kula-ghnānām—for those who destroy the family; kulasya—of the family; cha—also; patanti—fall; pitaraḥ—ancestors; hi—verily; eṣhām—their; lupta—deprived of; piṇḍodaka-kriyāḥ—performances of sacrificial offerings'),
('c9e2cec8-f68f-555d-83d3-e00463413f80'::uuid, 1, 43, 43, 43, 'दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः।

उत्साद्यन्ते जातिधर्माः कुलधर्माश्च शाश्वताः।।1.43।।', 'doṣhair etaiḥ kula-ghnānāṁ varṇa-saṅkara-kārakaiḥ
