('4ffc5d3e-8c4c-5fa3-89b0-c4e7d71b6b43'::uuid, 2, 22, 69, 69, 'वासांसि जीर्णानि यथा विहाय

नवानि गृह्णाति नरोऽपराणि।

तथा शरीराणि विहाय जीर्णा

न्यन्यानि संयाति नवानि देही।।2.22।।', 'vāsānsi jīrṇāni yathā vihāya
navāni gṛihṇāti naro ’parāṇi
tathā śharīrāṇi vihāya jīrṇānya
nyāni sanyāti navāni dehī', '[{"word":"vāsānsi","meaning":"garments"},{"word":"jīrṇāni","meaning":"worn-out"},{"word":"yathā","meaning":"as"},{"word":"vihāya","meaning":"sheds"},{"word":"navāni","meaning":"new"},{"word":"gṛihṇāti","meaning":"accepts"},{"word":"naraḥ","meaning":"a person"},{"word":"aparāṇi","meaning":"others"},{"word":"tathā","meaning":"likewise"},{"word":"śharīrāṇi","meaning":"bodies"},{"word":"vihāya","meaning":"casting off"},{"word":"jirṇāni","meaning":"worn-out"},{"word":"anyāni","meaning":"other"},{"word":"sanyāti","meaning":"enters"},{"word":"navāni","meaning":"new"},{"word":"dehī","meaning":"the embodied soul"}]'::jsonb, 'vāsānsi—garments; jīrṇāni—worn-out; yathā—as; vihāya—sheds; navāni—new; gṛihṇāti—accepts; naraḥ—a person; aparāṇi—others; tathā—likewise; śharīrāṇi—bodies; vihāya—casting off; jirṇāni—worn-out; anyāni—other; sanyāti—enters; navāni—new; dehī—the embodied soul'),
('0253ec8e-7e72-5e7c-aa1d-869d069a99b4'::uuid, 2, 23, 70, 70, 'नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः।

