('ccfec810-54c0-5e1a-92e0-071aeb0ada0d'::uuid, 2, 29, 76, 76, 'आश्चर्यवत्पश्यति कश्चिदेन

माश्चर्यवद्वदति तथैव चान्यः।

आश्चर्यवच्चैनमन्यः श्रृणोति

श्रुत्वाप्येनं वेद न चैव कश्चित्।।2.29।।', 'āśhcharya-vat paśhyati kaśhchid enan
āśhcharya-vad vadati tathaiva chānyaḥ
āśhcharya-vach chainam anyaḥ śhṛiṇoti
śhrutvāpyenaṁ veda na chaiva kaśhchit', '[{"word":"āśhcharya","meaning":"vat—as amazing"},{"word":"paśhyati","meaning":"see"},{"word":"kaśhchit","meaning":"someone"},{"word":"enam","meaning":"this soul"},{"word":"āśhcharya","meaning":"vat—as amazing"},{"word":"vadati","meaning":"speak of"},{"word":"tathā","meaning":"thus"},{"word":"eva","meaning":"indeed"},{"word":"cha","meaning":"and"},{"word":"anyaḥ","meaning":"other"},{"word":"āśhcharya","meaning":"vat—similarly amazing"},{"word":"cha","meaning":"also"},{"word":"enam","meaning":"this soul"},{"word":"anyaḥ","meaning":"others"},{"word":"śhṛiṇoti","meaning":"hear"},{"word":"śhrutvā","meaning":"having heard"},{"word":"api","meaning":"even"},{"word":"enam","meaning":"this soul"},{"word":"veda","meaning":"understand"},{"word":"na","meaning":"not"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"even"},{"word":"kaśhchit","meaning":"some"}]'::jsonb, 'āśhcharya-vat—as amazing; paśhyati—see; kaśhchit—someone; enam—this soul; āśhcharya-vat—as amazing; vadati—speak of; tathā—thus; eva—indeed; cha—and; anyaḥ—other; āśhcharya-vat—similarly amazing; cha—also; enam—this soul; anyaḥ—others; śhṛiṇoti—hear; śhrutvā—having heard; api—even; enam—this soul; veda—understand; na—not; cha—and; eva—even; kaśhchit—some'),
('7082d70a-857e-5855-be33-e2390c031f79'::uuid, 2, 30, 77, 77, 'देही नित्यमवध्योऽयं देहे सर्वस्य भारत।

तस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि।।2.30।।', 'dehī nityam avadhyo ’yaṁ dehe sarvasya bhārata
