('07c67223-61c4-5b7f-9170-2b794a5321bd'::uuid, 2, 43, 90, 90, 'कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम्।

क्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति।।2.43।।', 'kāmātmānaḥ svarga-parā 

 janma-karma-phala-pradām

 kriyā-viśeṣa-bahulāṁ

 bhogaiśvarya-gatiṁ prati', '[{"word":"kāmaātmānaḥ","meaning":"desirous   of  sense   gratification"},{"word":"svarga","meaning":"parāḥ—aiming to  achieve heavenly    planets"},{"word":"janma","meaning":"karma-phala-pradām—resulting  in  fruitive    action, good        birth,     etc."},{"word":"kriyā","meaning":"viśeṣa—pompous       ceremonies"},{"word":"bahulām","meaning":"various"},{"word":"bhoga","meaning":"sense       enjoyment"},{"word":"aiśvarya","meaning":"opulence"},{"word":"gatim","meaning":"progress"},{"word":"prati","meaning":"towards."}]'::jsonb, 'kāmaātmānaḥ—desirous   of  sense   gratification;  svarga-parāḥ—aiming to  achieve heavenly    planets;    janma-karma-phala-pradām—resulting  in  fruitive    action, good        birth,     etc.;      kriyā-viśeṣa—pompous       ceremonies;        bahulām—various; bhoga—sense       enjoyment;     aiśvarya—opulence;     gatim—progress;    prati—towards.'),
('e56a4507-80c7-5726-8608-49750de85282'::uuid, 2, 44, 91, 91, 'भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम्।

व्यवसायात्मिका बुद्धिः समाधौ न विधीयते।।2.44।।', 'bhogaiśwvarya-prasaktānāṁ tayāpahṛita-chetasām
vyavasāyātmikā buddhiḥ samādhau na vidhīyate', '[{"word":"bhoga","meaning":"gratification"},{"word":"aiśhwarya","meaning":"luxury"},{"word":"prasaktānām","meaning":"whose minds are deeply attached"},{"word":"tayā","meaning":"by that"},{"word":"apahṛita","meaning":"chetasām—bewildered in intellect"},{"word":"vyavasāya","meaning":"ātmikā—resolute"},{"word":"buddhiḥ","meaning":"intellect"},{"word":"samādhau","meaning":"fulfilment"},{"word":"na","meaning":"never"},{"word":"vidhīyate","meaning":"occurs"}]'::jsonb, 'bhoga—gratification; aiśhwarya—luxury; prasaktānām—whose minds are deeply attached; tayā—by that; apahṛita-chetasām—bewildered in intellect; vyavasāya-ātmikā—resolute; buddhiḥ—intellect; samādhau—fulfilment; na—never; vidhīyate—occurs'),
('728e922b-fecd-5162-8980-670240463820'::uuid, 2, 45, 92, 92, 'त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन।

निर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान्।।2.45।।', 'trai-guṇya-viṣhayā vedā nistrai-guṇyo bhavārjuna
nirdvandvo nitya-sattva-stho niryoga-kṣhema ātmavān', '[{"word":"trai","meaning":"guṇya—of the three modes of material nature"},{"word":"viṣhayāḥ","meaning":"subject matter"},{"word":"vedāḥ","meaning":"Vedic scriptures"},{"word":"nistrai","meaning":"guṇyaḥ—above the three modes of material nature, transcendental"},{"word":"bhava","meaning":"be"},{"word":"arjuna","meaning":"Arjun"},{"word":"nirdvandvaḥ","meaning":"free from dualities"},{"word":"nitya","meaning":"sattva-sthaḥ—eternally fixed in truth"},{"word":"niryoga","meaning":"kṣhemaḥ—unconcerned about gain and preservation"},{"word":"ātma","meaning":"vān—situated in the self"}]'::jsonb, 'trai-guṇya—of the three modes of material nature; viṣhayāḥ—subject matter; vedāḥ—Vedic scriptures; nistrai-guṇyaḥ—above the three modes of material nature, transcendental; bhava—be; arjuna—Arjun; nirdvandvaḥ—free from dualities; nitya-sattva-sthaḥ—eternally fixed in truth; niryoga-kṣhemaḥ—unconcerned about gain and preservation; ātma-vān—situated in the self'),
('67628f79-9ca9-576d-8f66-1e2dc4e33ae9'::uuid, 2, 46, 93, 93, 'यावानर्थ उदपाने सर्वतः संप्लुतोदके।

तावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः।।2.46।।', 'yāvān artha udapāne sarvataḥ samplutodake
tāvānsarveṣhu vedeṣhu brāhmaṇasya vijānataḥ', '[{"word":"yāvān","meaning":"whatever"},{"word":"arthaḥ","meaning":"purpose"},{"word":"uda","meaning":"pāne—a well of water"},{"word":"sarvataḥ","meaning":"in all respects"},{"word":"sampluta","meaning":"udake—by a large lake"},{"word":"tāvān","meaning":"that many"},{"word":"sarveṣhu","meaning":"in all"},{"word":"vedeṣhu","meaning":"Vedas"},{"word":"brāhmaṇasya","meaning":"one who realizes the Absolute Truth"},{"word":"vijānataḥ","meaning":"who is in complete knowledge"}]'::jsonb, 'yāvān—whatever; arthaḥ—purpose; uda-pāne—a well of water; sarvataḥ—in all respects; sampluta-udake—by a large lake; tāvān—that many; sarveṣhu—in all; vedeṣhu—Vedas; brāhmaṇasya—one who realizes the Absolute Truth; vijānataḥ—who is in complete knowledge'),
('171fcfe7-c27d-52d2-b6f0-399f559554a9'::uuid, 2, 47, 94, 94, 'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।

मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि।।2.47।।', 'karmaṇy-evādhikāras te mā phaleṣhu kadāchana
mā karma-phala-hetur bhūr mā te saṅgo ’stvakarmaṇi', '[{"word":"karmaṇi","meaning":"in prescribed duties"},{"word":"eva","meaning":"only"},{"word":"adhikāraḥ","meaning":"right"},{"word":"te","meaning":"your"},{"word":"mā","meaning":"not"},{"word":"phaleṣhu","meaning":"in the fruits"},{"word":"kadāchana","meaning":"at any time"},{"word":"mā","meaning":"never"},{"word":"karma","meaning":"phala—results of the activities"},{"word":"hetuḥ","meaning":"cause"},{"word":"bhūḥ","meaning":"be"},{"word":"mā","meaning":"not"},{"word":"te","meaning":"your"},{"word":"saṅgaḥ","meaning":"attachment"},{"word":"astu","meaning":"must be"},{"word":"akarmaṇi","meaning":"in inaction"}]'::jsonb, 'karmaṇi—in prescribed duties; eva—only; adhikāraḥ—right; te—your; mā—not; phaleṣhu—in the fruits; kadāchana—at any time; mā—never; karma-phala—results of the activities; hetuḥ—cause; bhūḥ—be; mā—not; te—your; saṅgaḥ—attachment; astu—must be; akarmaṇi—in inaction'),
('0e0b1b2e-6a84-5712-a371-214ea1800637'::uuid, 2, 48, 95, 95, 'योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय।

सिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते।।2.48।।', 'yoga-sthaḥ kuru karmāṇi saṅgaṁ tyaktvā dhanañjaya
siddhy-asiddhyoḥ samo bhūtvā samatvaṁ yoga uchyate', '[{"word":"yoga","meaning":"sthaḥ—being steadfast in yog"},{"word":"kuru","meaning":"perform"},{"word":"karmāṇi","meaning":"duties"},{"word":"saṅgam","meaning":"attachment"},{"word":"tyaktvā","meaning":"having abandoned"},{"word":"dhanañjaya","meaning":"Arjun"},{"word":"siddhi","meaning":"asiddhyoḥ—in success and failure"},{"word":"samaḥ","meaning":"equipoised"},{"word":"bhūtvā","meaning":"becoming"},{"word":"samatvam","meaning":"equanimity"},{"word":"yogaḥ","meaning":"Yog"},{"word":"uchyate","meaning":"is called"}]'::jsonb, 'yoga-sthaḥ—being steadfast in yog; kuru—perform; karmāṇi—duties; saṅgam—attachment; tyaktvā—having abandoned; dhanañjaya—Arjun; siddhi-asiddhyoḥ—in success and failure; samaḥ—equipoised; bhūtvā—becoming; samatvam—equanimity; yogaḥ—Yog; uchyate—is called'),
('b21f9548-9ec4-51c1-a594-5b328b45e15c'::uuid, 2, 49, 96, 96, 'दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय।

बुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः।।2.49।।', 'dūreṇa hy-avaraṁ karma buddhi-yogād dhanañjaya
buddhau śharaṇam anvichchha kṛipaṇāḥ phala-hetavaḥ', '[{"word":"dūreṇa","meaning":"(discrad) from far away"},{"word":"hi","meaning":"certainly"},{"word":"avaram","meaning":"inferior"},{"word":"karma","meaning":"reward-seeking actions"},{"word":"buddhi","meaning":"yogāt—with the intellect established in Divine knowledge"},{"word":"dhanañjaya","meaning":"Arjun"},{"word":"buddhau","meaning":"divine knowledge and insight"},{"word":"śharaṇam","meaning":"refuge"},{"word":"anvichchha","meaning":"seek"},{"word":"kṛipaṇāḥ","meaning":"miserly"},{"word":"phala","meaning":"hetavaḥ—those seeking fruits of their work"}]'::jsonb, 'dūreṇa—(discrad) from far away; hi—certainly; avaram—inferior; karma—reward-seeking actions; buddhi-yogāt—with the intellect established in Divine knowledge; dhanañjaya—Arjun; buddhau—divine knowledge and insight; śharaṇam—refuge; anvichchha—seek; kṛipaṇāḥ—miserly; phala-hetavaḥ—those seeking fruits of their work'),
('a7ef20f0-8141-500e-947b-fc122959469d'::uuid, 2, 50, 97, 97, 'बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते।

तस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम्।।2.50।।', 'buddhi-yukto jahātīha ubhe sukṛita-duṣhkṛite
tasmād yogāya yujyasva yogaḥ karmasu kauśhalam', '[{"word":"buddhi","meaning":"yuktaḥ—endowed with wisdom"},{"word":"jahāti","meaning":"get rid of"},{"word":"iha","meaning":"in this life"},{"word":"ubhe","meaning":"both"},{"word":"sukṛita","meaning":"duṣhkṛite—good and bad deeds"},{"word":"tasmāt","meaning":"therefore"},{"word":"yogāya","meaning":"for Yog"},{"word":"yujyasva","meaning":"strive for"},{"word":"yogaḥ","meaning":"yog is"},{"word":"karmasu kauśhalam","meaning":"the art of working skillfully"}]'::jsonb, 'buddhi-yuktaḥ—endowed with wisdom; jahāti—get rid of; iha—in this life; ubhe—both; sukṛita-duṣhkṛite—good and bad deeds; tasmāt—therefore; yogāya—for Yog; yujyasva—strive for; yogaḥ—yog is; karmasu kauśhalam—the art of working skillfully'),
('83376527-d732-5ea5-b0bd-5951f95aeeea'::uuid, 2, 51, 98, 98, 'कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः।

जन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम्।।2.51।।', 'karma-jaṁ buddhi-yuktā hi phalaṁ tyaktvā manīṣhiṇaḥ
janma-bandha-vinirmuktāḥ padaṁ gachchhanty-anāmayam', '[{"word":"karma","meaning":"jam—born of fruitive actions"},{"word":"buddhi","meaning":"yuktāḥ—endowed with equanimity of intellect"},{"word":"hi","meaning":"as"},{"word":"phalam","meaning":"fruits"},{"word":"tyaktvā","meaning":"abandoning"},{"word":"manīṣhiṇaḥ","meaning":"the wise"},{"word":"janma","meaning":"bandha-vinirmuktāḥ—freedom from the bondage of life and death"},{"word":"padam","meaning":"state"},{"word":"gachchhanti","meaning":"attain"},{"word":"anāmayam","meaning":"devoid of sufferings"}]'::jsonb, 'karma-jam—born of fruitive actions; buddhi-yuktāḥ—endowed with equanimity of intellect; hi—as; phalam—fruits; tyaktvā—abandoning; manīṣhiṇaḥ—the wise; janma-bandha-vinirmuktāḥ—freedom from the bondage of life and death; padam—state; gachchhanti—attain; anāmayam—devoid of sufferings'),
('204c7772-8eaf-5806-b490-e18d24631a17'::uuid, 2, 52, 99, 99, 'यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति।

तदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च।।2.52।।', 'yadā te moha-kalilaṁ buddhir vyatitariṣhyati
tadā gantāsi nirvedaṁ śhrotavyasya śhrutasya cha', '[{"word":"yadā","meaning":"when"},{"word":"te","meaning":"your"},{"word":"moha","meaning":"delusion"},{"word":"kalilam","meaning":"quagmire"},{"word":"buddhiḥ","meaning":"intellect"},{"word":"vyatitariṣhyati","meaning":"crosses"},{"word":"tadā","meaning":"then"},{"word":"gantāsi","meaning":"you shall acquire"},{"word":"nirvedam","meaning":"indifferent"},{"word":"śhrotavyasya","meaning":"to what is yet to be heard"},{"word":"śhrutasya","meaning":"to what has been heard"},{"word":"cha","meaning":"and"}]'::jsonb, 'yadā—when; te—your; moha—delusion; kalilam—quagmire; buddhiḥ—intellect; vyatitariṣhyati—crosses; tadā—then; gantāsi—you shall acquire; nirvedam—indifferent; śhrotavyasya—to what is yet to be heard; śhrutasya—to what has been heard; cha—and'),
('f6ffb97a-9871-5c92-af83-c58d73e50beb'::uuid, 2, 53, 100, 100, 'श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला।

समाधावचला बुद्धिस्तदा योगमवाप्स्यसि।।2.53।।', 'śhruti-vipratipannā te yadā sthāsyati niśhchalā
samādhāv-achalā buddhis tadā yogam avāpsyasi', '[{"word":"śhruti","meaning":"vipratipannā—not allured by the fruitive sections of the Vedas"},{"word":"te","meaning":"your"},{"word":"yadā","meaning":"when"},{"word":"sthāsyati","meaning":"remains"},{"word":"niśhchalā","meaning":"steadfast"},{"word":"samādhau","meaning":"in divine consciousness"},{"word":"achalā","meaning":"steadfast"},{"word":"buddhiḥ","meaning":"intellect"},{"word":"tadā","meaning":"at that time"},{"word":"yogam","meaning":"Yog"},{"word":"avāpsyasi","meaning":"you will attain"}]'::jsonb, 'śhruti-vipratipannā—not allured by the fruitive sections of the Vedas; te—your; yadā—when; sthāsyati—remains; niśhchalā—steadfast; samādhau—in divine consciousness; achalā—steadfast; buddhiḥ—intellect; tadā—at that time; yogam—Yog; avāpsyasi—you will attain')
