INSERT INTO public.gita_verses (id, chapter_number, verse_number, verse_order, external_id, sanskrit, transliteration, word_meanings, word_meanings_raw) VALUES
('48da304c-7d2f-59bf-9165-e8ef0a658aa0'::uuid, 2, 54, 101, 101, 'अर्जुन उवाच

स्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव।

स्थितधीः किं प्रभाषेत किमासीत व्रजेत किम्।।2.54।।', 'arjuna uvācha
sthita-prajñasya kā bhāṣhā samādhi-sthasya keśhava
sthita-dhīḥ kiṁ prabhāṣheta kim āsīta vrajeta kim', '[{"word":"arjunaḥ uvācha","meaning":"Arjun said"},{"word":"sthita","meaning":"prajñasya—one with steady intellect"},{"word":"kā","meaning":"what"},{"word":"bhāṣhā","meaning":"talk"},{"word":"samādhi","meaning":"sthasya—situated in divine consciousness"},{"word":"keśhava","meaning":"Shree Krishna, killer of the Keshi Demon"},{"word":"sthita","meaning":"dhīḥ—enlightened person"},{"word":"kim","meaning":"what"},{"word":"prabhāṣheta","meaning":"talks"},{"word":"kim","meaning":"how"},{"word":"āsīta","meaning":"sits"},{"word":"vrajeta","meaning":"walks"},{"word":"kim","meaning":"how"}]'::jsonb, 'arjunaḥ uvācha—Arjun said; sthita-prajñasya—one with steady intellect; kā—what; bhāṣhā—talk; samādhi-sthasya—situated in divine consciousness; keśhava—Shree Krishna, killer of the Keshi Demon; sthita-dhīḥ—enlightened person; kim—what; prabhāṣheta—talks; kim—how; āsīta—sits; vrajeta—walks; kim—how'),
('ba58cbf1-a87f-595d-a200-942017edb805'::uuid, 2, 55, 102, 102, 'श्री भगवानुवाच

प्रजहाति यदा कामान् सर्वान् पार्थ मनोगतान्।

आत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते।।2.55।।', 'śhrī bhagavān uvācha
prajahāti yadā kāmān sarvān pārtha mano-gatān
ātmany-evātmanā tuṣhṭaḥ sthita-prajñas tadochyate', '[{"word":"śhrī","meaning":"bhagavān uvācha—The Supreme Lord said"},{"word":"prajahāti","meaning":"discards"},{"word":"yadā","meaning":"when"},{"word":"kāmān","meaning":"selfish desires"},{"word":"sarvān","meaning":"all"},{"word":"pārtha","meaning":"Arjun, the son of Pritha"},{"word":"manaḥ","meaning":"gatān—of the mind"},{"word":"ātmani","meaning":"of the self"},{"word":"eva","meaning":"only"},{"word":"ātmanā","meaning":"by the purified mind"},{"word":"tuṣhṭaḥ","meaning":"satisfied"},{"word":"sthita","meaning":"prajñaḥ—one with steady intellect"},{"word":"tadā","meaning":"at that time"},{"word":"uchyate","meaning":"is said"}]'::jsonb, 'śhrī-bhagavān uvācha—The Supreme Lord said; prajahāti—discards; yadā—when; kāmān—selfish desires; sarvān—all; pārtha—Arjun, the son of Pritha; manaḥ-gatān—of the mind; ātmani—of the self; eva—only; ātmanā—by the purified mind; tuṣhṭaḥ—satisfied; sthita-prajñaḥ—one with steady intellect; tadā—at that time; uchyate—is said'),
('a449720e-f078-52b6-8bc9-90e5a7ca665b'::uuid, 2, 56, 103, 103, 'दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः।

वीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते।।2.56।।', 'duḥkheṣhv-anudvigna-manāḥ sukheṣhu vigata-spṛihaḥ
vīta-rāga-bhaya-krodhaḥ sthita-dhīr munir uchyate', '[{"word":"duḥkheṣhu","meaning":"amidst miseries"},{"word":"anudvigna","meaning":"manāḥ—one whose mind is undisturbed"},{"word":"sukheṣhu","meaning":"in pleasure"},{"word":"vigata","meaning":"spṛihaḥ—without craving"},{"word":"vīta","meaning":"free from"},{"word":"rāga","meaning":"attachment"},{"word":"bhaya","meaning":"fear"},{"word":"krodhaḥ","meaning":"anger"},{"word":"sthita","meaning":"dhīḥ—enlightened person"},{"word":"muniḥ","meaning":"a sage"},{"word":"uchyate","meaning":"is called"}]'::jsonb, 'duḥkheṣhu—amidst miseries; anudvigna-manāḥ—one whose mind is undisturbed; sukheṣhu—in pleasure; vigata-spṛihaḥ—without craving; vīta—free from; rāga—attachment; bhaya—fear; krodhaḥ—anger; sthita-dhīḥ—enlightened person; muniḥ—a sage; uchyate—is called'),
('f093da7c-c9dd-5059-b8cf-1f51d7f63464'::uuid, 2, 57, 104, 104, 'यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम्।

नाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता।।2.57।।', 'yaḥ sarvatrānabhisnehas tat tat prāpya śhubhāśhubham
nābhinandati na dveṣhṭi tasya prajñā pratiṣhṭhitā', '[{"word":"yaḥ","meaning":"who"},{"word":"sarvatra","meaning":"in all conditions"},{"word":"anabhisnehaḥ","meaning":"unattached"},{"word":"tat","meaning":"that"},{"word":"tat","meaning":"that"},{"word":"prāpya","meaning":"attaining"},{"word":"śhubha","meaning":"good"},{"word":"aśhubham","meaning":"evil"},{"word":"na","meaning":"neither"},{"word":"abhinandati","meaning":"delight in"},{"word":"na","meaning":"nor"},{"word":"dveṣhṭi","meaning":"dejected by"},{"word":"tasya","meaning":"his"},{"word":"prajñā","meaning":"knowledge"},{"word":"pratiṣhṭhitā","meaning":"is fixed"}]'::jsonb, 'yaḥ—who; sarvatra—in all conditions; anabhisnehaḥ—unattached; tat—that; tat—that; prāpya—attaining; śhubha—good; aśhubham—evil; na—neither; abhinandati—delight in; na—nor; dveṣhṭi—dejected by; tasya—his; prajñā—knowledge; pratiṣhṭhitā—is fixed'),
('f6f6b1ba-77f8-5359-956d-1b13817da029'::uuid, 2, 58, 105, 105, 'यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः।

इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता।।2.58।।', 'yadā sanharate chāyaṁ kūrmo ’ṅgānīva sarvaśhaḥ
indriyāṇīndriyārthebhyas tasya prajñā pratiṣhṭhitā', '[{"word":"yadā","meaning":"when"},{"word":"sanharate","meaning":"withdraw"},{"word":"cha","meaning":"and"},{"word":"ayam","meaning":"this"},{"word":"kūrmaḥ","meaning":"tortoise"},{"word":"aṅgāni","meaning":"limbs"},{"word":"iva","meaning":"as"},{"word":"sarvaśhaḥ","meaning":"fully"},{"word":"indriyāṇi","meaning":"senses"},{"word":"indriya","meaning":"arthebhyaḥ—from the sense objects"},{"word":"tasya","meaning":"his"},{"word":"prajñā","meaning":"divine wisdom"},{"word":"pratiṣhṭhitā","meaning":"fixed in"}]'::jsonb, 'yadā—when; sanharate—withdraw; cha—and; ayam—this; kūrmaḥ—tortoise; aṅgāni—limbs; iva—as; sarvaśhaḥ—fully; indriyāṇi—senses; indriya-arthebhyaḥ—from the sense objects; tasya—his; prajñā—divine wisdom; pratiṣhṭhitā—fixed in'),
('8ba4b3c6-4719-5eba-b3b8-25d05d952d5b'::uuid, 2, 59, 106, 106, 'विषया विनिवर्तन्ते निराहारस्य देहिनः।

रसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते।।2.59।।', 'viṣhayā vinivartante nirāhārasya dehinaḥ
