('58b673ae-10fe-5838-994e-4ca18a3a8254'::uuid, 4, 1, 163, 163, 'श्री भगवानुवाच

इमं विवस्वते योगं प्रोक्तवानहमव्ययम्।

विवस्वान् मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत्।।4.1।।', 'śhrī bhagavān uvācha
imaṁ vivasvate yogaṁ proktavān aham avyayam
vivasvān manave prāha manur ikṣhvākave ’bravīt', '[{"word":"śhrī","meaning":"bhagavān uvācha—the Supreme Lord Shree Krishna said"},{"word":"imam","meaning":"this"},{"word":"vivasvate","meaning":"to the Sun-god"},{"word":"yogam","meaning":"the science of Yog"},{"word":"proktavān","meaning":"taught"},{"word":"aham","meaning":"I"},{"word":"avyayam","meaning":"eternal"},{"word":"vivasvān","meaning":"Sun-god"},{"word":"manave","meaning":"to Manu, the original progenitor of humankind"},{"word":"prāha","meaning":"told"},{"word":"manuḥ","meaning":"Manu"},{"word":"ikṣhvākave","meaning":"to Ikshvaku, first king of the Solar dynasty"},{"word":"abravīt","meaning":"instructed"}]'::jsonb, 'śhrī-bhagavān uvācha—the Supreme Lord Shree Krishna said; imam—this; vivasvate—to the Sun-god; yogam—the science of Yog; proktavān—taught; aham—I; avyayam—eternal; vivasvān—Sun-god; manave—to Manu, the original progenitor of humankind; prāha—told; manuḥ—Manu; ikṣhvākave—to Ikshvaku, first king of the Solar dynasty; abravīt—instructed'),
('a6324ec2-34f0-50d8-96de-e96c15274f85'::uuid, 4, 2, 164, 164, 'एवं परम्पराप्राप्तमिमं राजर्षयो विदुः।

स कालेनेह महता योगो नष्टः परन्तप।।4.2।।', 'evaṁ paramparā-prāptam imaṁ rājarṣhayo viduḥ
