('35475557-6f1f-52d3-bceb-e87eb3e21f08'::uuid, 4, 35, 197, 197, 'यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव।

येन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि।।4.35।।', 'yaj jñātvā na punar moham evaṁ yāsyasi pāṇḍava
yena bhūtānyaśheṣheṇa drakṣhyasyātmanyatho mayi', '[{"word":"yat","meaning":"which"},{"word":"jñātvā","meaning":"having known"},{"word":"na","meaning":"never"},{"word":"punaḥ","meaning":"again"},{"word":"moham","meaning":"delusion"},{"word":"evam","meaning":"like this"},{"word":"yāsyasi","meaning":"you shall get"},{"word":"pāṇḍava","meaning":"Arjun, the son of Pandu"},{"word":"yena","meaning":"by this"},{"word":"bhūtāni","meaning":"living beings"},{"word":"aśheṣhāṇi","meaning":"all"},{"word":"drakṣhyasi","meaning":"you will see"},{"word":"ātmani","meaning":"within me (Shree Krishna)"},{"word":"atho","meaning":"that is to say"},{"word":"mayi","meaning":"in me"}]'::jsonb, 'yat—which; jñātvā—having known; na—never; punaḥ—again; moham—delusion; evam—like this; yāsyasi—you shall get; pāṇḍava—Arjun, the son of Pandu; yena—by this; bhūtāni—living beings; aśheṣhāṇi—all; drakṣhyasi—you will see; ātmani—within me (Shree Krishna); atho—that is to say; mayi—in me'),
('807330e6-c4f2-501e-95dd-7a8f16ceaa35'::uuid, 4, 36, 198, 198, 'अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः।

सर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि।।4.36।।', 'api ched asi pāpebhyaḥ sarvebhyaḥ pāpa-kṛit-tamaḥ
