('b007c082-879b-54b7-9e6e-837da9dd19f4'::uuid, 4, 37, 199, 199, 'यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन।

ज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा।।4.37।।', 'yathaidhānsi samiddho ’gnir bhasma-sāt kurute ’rjuna
jñānāgniḥ sarva-karmāṇi bhasma-sāt kurute tathā', '[{"word":"yathā","meaning":"as"},{"word":"edhānsi","meaning":"firewood"},{"word":"samiddhaḥ","meaning":"blazing"},{"word":"agniḥ","meaning":"fire"},{"word":"bhasma","meaning":"sāt—to ashes"},{"word":"kurute","meaning":"turns"},{"word":"arjuna","meaning":"Arjun"},{"word":"jñāna","meaning":"agniḥ—the fire of knowledge"},{"word":"sarva","meaning":"karmāṇi—all reactions from material activities"},{"word":"bhasma","meaning":"sāt—to ashes"},{"word":"kurute","meaning":"it turns"},{"word":"tathā","meaning":"similarly"}]'::jsonb, 'yathā—as; edhānsi—firewood; samiddhaḥ—blazing; agniḥ—fire; bhasma-sāt—to ashes; kurute—turns; arjuna—Arjun; jñāna-agniḥ—the fire of knowledge; sarva-karmāṇi—all reactions from material activities; bhasma-sāt—to ashes; kurute—it turns; tathā—similarly'),
('8bcec931-e765-587d-8aff-36369bd1b5d6'::uuid, 4, 38, 200, 200, 'न हि ज्ञानेन सदृशं पवित्रमिह विद्यते।

तत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति।।4.38।।', 'na hi jñānena sadṛiśhaṁ pavitramiha vidyate
tatsvayaṁ yogasansiddhaḥ kālenātmani vindati', '[{"word":"na","meaning":"not"},{"word":"hi","meaning":"certainly"},{"word":"jñānena","meaning":"with divine knowledge"},{"word":"sadṛiśham","meaning":"like"},{"word":"pavitram","meaning":"pure"},{"word":"iha","meaning":"in this world"},{"word":"vidyate","meaning":"exists"},{"word":"tat","meaning":"that"},{"word":"svayam","meaning":"oneself"},{"word":"yoga","meaning":"practice of yog"},{"word":"sansiddhaḥ","meaning":"he who has attained perfection"},{"word":"kālena","meaning":"in course of time"},{"word":"ātmani","meaning":"wihtin the heart"},{"word":"vindati","meaning":"finds"}]'::jsonb, 'na—not; hi—certainly; jñānena—with divine knowledge; sadṛiśham—like; pavitram—pure; iha—in this world; vidyate—exists; tat—that; svayam—oneself; yoga—practice of yog; sansiddhaḥ—he who has attained perfection; kālena—in course of time; ātmani—wihtin the heart; vindati—finds')
