INSERT INTO public.gita_verses (id, chapter_number, verse_number, verse_order, external_id, sanskrit, transliteration, word_meanings, word_meanings_raw) VALUES
('929471c5-5cd7-554f-999c-3dd3cc1a041e'::uuid, 4, 39, 201, 201, 'श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः।

ज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति।।4.39।।', 'śhraddhāvān labhate jñānaṁ tat-paraḥ sanyatendriyaḥ
jñānaṁ labdhvā parāṁ śhāntim achireṇādhigachchhati', '[{"word":"śhraddhā","meaning":"vān—a faithful person"},{"word":"labhate","meaning":"achieves"},{"word":"jñānam","meaning":"divine knowledge"},{"word":"tat","meaning":"paraḥ—devoted (to that)"},{"word":"sanyata","meaning":"controlled"},{"word":"indriyaḥ","meaning":"senses"},{"word":"jñānam","meaning":"transcendental knowledge"},{"word":"labdhvā","meaning":"having achieved"},{"word":"parām","meaning":"supreme"},{"word":"śhāntim","meaning":"peace"},{"word":"achireṇa","meaning":"without delay"},{"word":"adhigachchhati","meaning":"attains"}]'::jsonb, 'śhraddhā-vān—a faithful person; labhate—achieves; jñānam—divine knowledge; tat-paraḥ—devoted (to that); sanyata—controlled; indriyaḥ—senses; jñānam—transcendental knowledge; labdhvā—having achieved; parām—supreme; śhāntim—peace; achireṇa—without delay; adhigachchhati—attains'),
('939bac97-0ce4-51bb-a5e9-0b2a669eea51'::uuid, 4, 40, 202, 202, 'अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति।

नायं लोकोऽस्ति न परो न सुखं संशयात्मनः।।4.40।।', 'ajñaśh chāśhraddadhānaśh cha sanśhayātmā vinaśhyati
nāyaṁ loko ’sti na paro na sukhaṁ sanśhayātmanaḥ', '[{"word":"ajñaḥ","meaning":"the ignorant"},{"word":"cha","meaning":"and"},{"word":"aśhraddadhānaḥ","meaning":"without faith"},{"word":"cha","meaning":"and"},{"word":"sanśhaya","meaning":"skeptical"},{"word":"ātmā","meaning":"a person"},{"word":"vinaśhyati","meaning":"falls down"},{"word":"na","meaning":"never"},{"word":"ayam","meaning":"in this"},{"word":"lokaḥ","meaning":"world"},{"word":"asti","meaning":"is"},{"word":"na","meaning":"not"},{"word":"paraḥ","meaning":"in the next"},{"word":"na","meaning":"not"},{"word":"sukham","meaning":"happiness"},{"word":"sanśhaya","meaning":"ātmanaḥ—for the skeptical soul"}]'::jsonb, 'ajñaḥ—the ignorant; cha—and; aśhraddadhānaḥ—without faith; cha—and; sanśhaya—skeptical; ātmā—a person; vinaśhyati—falls down; na—never; ayam—in this; lokaḥ—world; asti—is; na—not; paraḥ—in the next; na—not; sukham—happiness; sanśhaya-ātmanaḥ—for the skeptical soul'),
('1ddda8f6-3172-5749-83ed-9cf594fb9c4d'::uuid, 4, 41, 203, 203, 'योगसंन्यस्तकर्माणं ज्ञानसंछिन्नसंशयम्।

आत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय।।4.41।।', 'yoga-sannyasta-karmāṇaṁ jñāna-sañchhinna-sanśhayam
ātmavantaṁ na karmāṇi nibadhnanti dhanañjaya', '[{"word":"yoga","meaning":"sannyasta-karmāṇam—those who renounce ritualistic karm, dedicating their body, mind, and soul to God"},{"word":"jñāna","meaning":"by knowledge"},{"word":"sañchhinna","meaning":"dispelled"},{"word":"sanśhayam","meaning":"doubts"},{"word":"ātma","meaning":"vantam—situated in knowledge of the self"},{"word":"na","meaning":"not"},{"word":"karmāṇi","meaning":"actions"},{"word":"nibadhnanti","meaning":"bind"},{"word":"dhanañjaya","meaning":"Arjun, the conqueror of wealth"}]'::jsonb, 'yoga-sannyasta-karmāṇam—those who renounce ritualistic karm, dedicating their body, mind, and soul to God; jñāna—by knowledge; sañchhinna—dispelled; sanśhayam—doubts; ātma-vantam—situated in knowledge of the self; na—not; karmāṇi—actions; nibadhnanti—bind; dhanañjaya—Arjun, the conqueror of wealth'),
('5678cecb-0ad5-592a-bce6-67ff1f34755b'::uuid, 4, 42, 204, 204, 'तस्मादज्ञानसंभूतं हृत्स्थं ज्ञानासिनाऽऽत्मनः।

छित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत।।4.42।।', 'tasmād ajñāna-sambhūtaṁ hṛit-sthaṁ jñānāsinātmanaḥ
chhittvainaṁ sanśhayaṁ yogam ātiṣhṭhottiṣhṭha bhārata', '[{"word":"tasmāt","meaning":"therefore"},{"word":"ajñāna","meaning":"sambhūtam—born of ignorance"},{"word":"hṛit","meaning":"stham—situated in the heart"},{"word":"jñāna","meaning":"of knowledge"},{"word":"asinā","meaning":"with the sword"},{"word":"ātmanaḥ","meaning":"of the self"},{"word":"chhittvā","meaning":"cut asunder"},{"word":"enam","meaning":"this"},{"word":"sanśhayam","meaning":"doubt"},{"word":"yogam","meaning":"in karm yog"},{"word":"ātiṣhṭha","meaning":"take shelter"},{"word":"uttiṣhṭha","meaning":"arise"},{"word":"bhārata","meaning":"Arjun, descendant of Bharat"}]'::jsonb, 'tasmāt—therefore; ajñāna-sambhūtam—born of ignorance; hṛit-stham—situated in the heart; jñāna—of knowledge; asinā—with the sword; ātmanaḥ—of the self; chhittvā—cut asunder; enam—this; sanśhayam—doubt; yogam—in karm yog; ātiṣhṭha—take shelter; uttiṣhṭha—arise; bhārata—Arjun, descendant of Bharat'),
('88f4d63b-a852-5707-bc0b-f9c1ed0d7c0c'::uuid, 5, 1, 205, 205, 'अर्जुन उवाच

संन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि।

यच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्िचतम्।।5.1।।', 'arjuna uvācha
sannyāsaṁ karmaṇāṁ kṛiṣhṇa punar yogaṁ cha śhansasi
yach chhreya etayor ekaṁ tan me brūhi su-niśhchitam', '[{"word":"arjunaḥ uvācha","meaning":"Arjun said"},{"word":"sanyāsam","meaning":"renunciation"},{"word":"karmaṇām","meaning":"of actions"},{"word":"kṛiṣhṇa","meaning":"Shree Krishna"},{"word":"punaḥ","meaning":"again"},{"word":"yogam","meaning":"about karm yog"},{"word":"cha","meaning":"also"},{"word":"śhansasi","meaning":"you praise"},{"word":"yat","meaning":"which"},{"word":"śhreyaḥ","meaning":"more beneficial"},{"word":"etayoḥ","meaning":"of the two"},{"word":"ekam","meaning":"one"},{"word":"tat","meaning":"that"},{"word":"me","meaning":"unto me"},{"word":"brūhi","meaning":"please tell"},{"word":"su","meaning":"niśhchitam—conclusively"}]'::jsonb, 'arjunaḥ uvācha—Arjun said; sanyāsam—renunciation; karmaṇām—of actions; kṛiṣhṇa—Shree Krishna; punaḥ—again; yogam—about karm yog; cha—also; śhansasi—you praise; yat—which; śhreyaḥ—more beneficial; etayoḥ—of the two; ekam—one; tat—that; me—unto me; brūhi—please tell; su-niśhchitam—conclusively'),
('6d8df0dd-5159-5002-bf70-97e4fa98808d'::uuid, 5, 2, 206, 206, 'श्री भगवानुवाच

संन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ।

तयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते।।5.2।।', 'śhrī bhagavān uvācha
sannyāsaḥ karma-yogaśh cha niḥśhreyasa-karāvubhau
tayos tu karma-sannyāsāt karma-yogo viśhiṣhyate', '[{"word":"śhrī","meaning":"bhagavān uvācha—the Supreme Lord said"},{"word":"sanyāsaḥ","meaning":"renunciation"},{"word":"karma","meaning":"yogaḥ—working in devotion"},{"word":"cha","meaning":"and"},{"word":"niḥśhreyasa","meaning":"karau—lead to the supreme goal"},{"word":"ubhau","meaning":"both"},{"word":"tayoḥ","meaning":"of the two"},{"word":"tu","meaning":"but"},{"word":"karma","meaning":"sanyāsāt—renunciation of actions"},{"word":"karma","meaning":"yogaḥ—working in devotion"},{"word":"viśhiṣhyate","meaning":"is superior"}]'::jsonb, 'śhrī-bhagavān uvācha—the Supreme Lord said; sanyāsaḥ—renunciation; karma-yogaḥ—working in devotion; cha—and; niḥśhreyasa-karau—lead to the supreme goal; ubhau—both; tayoḥ—of the two; tu—but; karma-sanyāsāt—renunciation of actions; karma-yogaḥ—working in devotion; viśhiṣhyate—is superior'),
('f655713a-0a3a-5cb5-aa91-07bc0a0b076f'::uuid, 5, 3, 207, 207, 'ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति।

निर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते।।5.3।।', 'jñeyaḥ sa nitya-sannyāsī yo na dveṣhṭi na kāṅkṣhati
nirdvandvo hi mahā-bāho sukhaṁ bandhāt pramuchyate', '[{"word":"jñeyaḥ","meaning":"should be considered"},{"word":"saḥ","meaning":"that person"},{"word":"nitya","meaning":"always"},{"word":"sanyāsī","meaning":"practising renunciation"},{"word":"yaḥ","meaning":"who"},{"word":"na","meaning":"never"},{"word":"dveṣhṭi","meaning":"hate"},{"word":"na","meaning":"nor"},{"word":"kāṅkṣhati","meaning":"desire"},{"word":"nirdvandvaḥ","meaning":"free from all dualities"},{"word":"hi","meaning":"certainly"},{"word":"mahā","meaning":"bāho—mighty-armed one"},{"word":"sukham","meaning":"easily"},{"word":"bandhāt","meaning":"from bondage"},{"word":"pramuchyate","meaning":"is liberated"}]'::jsonb, 'jñeyaḥ—should be considered; saḥ—that person; nitya—always; sanyāsī—practising renunciation; yaḥ—who; na—never; dveṣhṭi—hate; na—nor; kāṅkṣhati—desire; nirdvandvaḥ—free from all dualities; hi—certainly; mahā-bāho—mighty-armed one; sukham—easily; bandhāt—from bondage; pramuchyate—is liberated'),
('2931a370-49a7-5de0-a3e3-17427394a2b0'::uuid, 5, 4, 208, 208, 'सांख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः।

एकमप्यास्थितः सम्यगुभयोर्विन्दते फलम्।।5.4।।', 'sānkhya-yogau pṛithag bālāḥ pravadanti na paṇḍitāḥ
ekamapyāsthitaḥ samyag ubhayor vindate phalam', '[{"word":"sānkhya","meaning":"renunciation of actions"},{"word":"yogau","meaning":"karm yog"},{"word":"pṛithak","meaning":"different"},{"word":"bālāḥ","meaning":"the ignorant"},{"word":"pravadanti","meaning":"say"},{"word":"na","meaning":"never"},{"word":"paṇḍitāḥ","meaning":"the learned"},{"word":"ekam","meaning":"in one"},{"word":"api","meaning":"even"},{"word":"āsthitaḥ","meaning":"being situated"},{"word":"samyak","meaning":"completely"},{"word":"ubhayoḥ","meaning":"of both"},{"word":"vindate","meaning":"achieve"},{"word":"phalam","meaning":"the result"}]'::jsonb, 'sānkhya—renunciation of actions; yogau—karm yog; pṛithak—different; bālāḥ—the ignorant; pravadanti—say; na—never; paṇḍitāḥ—the learned; ekam—in one; api—even; āsthitaḥ—being situated; samyak—completely; ubhayoḥ—of both; vindate—achieve; phalam—the result'),
('83bca8da-0437-5180-9274-1511fad6b9a2'::uuid, 5, 5, 209, 209, 'यत्सांख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते।

एकं सांख्यं च योगं च यः पश्यति स पश्यति।।5.5।।', 'yat sānkhyaiḥ prāpyate sthānaṁ tad yogair api gamyate
ekaṁ sānkhyaṁ cha yogaṁ cha yaḥ paśhyati sa paśhyati', '[{"word":"yat","meaning":"what"},{"word":"sānkhyaiḥ","meaning":"by means of karm sanyās"},{"word":"prāpyate","meaning":"is attained"},{"word":"sthānam","meaning":"place"},{"word":"tat","meaning":"that"},{"word":"yogaiḥ","meaning":"by working in devotion"},{"word":"api","meaning":"also"},{"word":"gamyate","meaning":"is attained"},{"word":"ekam","meaning":"one"},{"word":"sānkhyam","meaning":"renunciation of actions"},{"word":"cha","meaning":"and"},{"word":"yogam","meaning":"karm yog"},{"word":"cha","meaning":"and"},{"word":"yaḥ","meaning":"who"},{"word":"paśhyati","meaning":"sees"},{"word":"saḥ","meaning":"that person"},{"word":"paśhyati","meaning":"actually sees"}]'::jsonb, 'yat—what; sānkhyaiḥ—by means of karm sanyās; prāpyate—is attained; sthānam—place; tat—that; yogaiḥ—by working in devotion; api—also; gamyate—is attained; ekam—one; sānkhyam—renunciation of actions; cha—and; yogam—karm yog; cha—and; yaḥ—who; paśhyati—sees; saḥ—that person; paśhyati—actually sees'),
('d606c05f-ad99-5ded-9efa-883cc09de097'::uuid, 5, 6, 210, 210, 'संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः।

योगयुक्तो मुनिर्ब्रह्म नचिरेणाधिगच्छति।।5.6।।', 'sannyāsas tu mahā-bāho duḥkham āptum ayogataḥ
yoga-yukto munir brahma na chireṇādhigachchhati', '[{"word":"sanyāsaḥ","meaning":"renunciation"},{"word":"tu","meaning":"but"},{"word":"mahā","meaning":"bāho—mighty-armed one"},{"word":"duḥkham","meaning":"distress"},{"word":"āptum","meaning":"attains"},{"word":"ayogataḥ","meaning":"without karm yog"},{"word":"yoga","meaning":"yuktaḥ—one who is adept in karm yog"},{"word":"muniḥ","meaning":"a sage"},{"word":"brahma","meaning":"Brahman"},{"word":"na chireṇa","meaning":"quickly"},{"word":"adhigachchhati","meaning":"goes"}]'::jsonb, 'sanyāsaḥ—renunciation; tu—but; mahā-bāho—mighty-armed one; duḥkham—distress; āptum—attains; ayogataḥ—without karm yog; yoga-yuktaḥ—one who is adept in karm yog; muniḥ—a sage; brahma—Brahman; na chireṇa—quickly; adhigachchhati—goes'),
('106aff34-3def-560a-8582-65ef9fb1d2ca'::uuid, 5, 7, 211, 211, 'योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः।

सर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते।।5.7।।', 'yoga-yukto viśhuddhātmā vijitātmā jitendriyaḥ
sarva-bhūtātma-bhūtātmā kurvann api na lipyate', '[{"word":"yoga","meaning":"yuktaḥ—united in consciousness with God"},{"word":"viśhuddha","meaning":"ātmā—one with purified intellect"},{"word":"vijita","meaning":"ātmā—one who has conquered the mind"},{"word":"jita","meaning":"indriyaḥ—having conquered the senses"},{"word":"sarva","meaning":"bhūta-ātma-bhūta-ātmā—one who sees the Soul of all souls in every living being"},{"word":"kurvan","meaning":"performing"},{"word":"api","meaning":"although"},{"word":"na","meaning":"never"},{"word":"lipyate","meaning":"entangled"}]'::jsonb, 'yoga-yuktaḥ—united in consciousness with God; viśhuddha-ātmā—one with purified intellect; vijita-ātmā—one who has conquered the mind; jita-indriyaḥ—having conquered the senses; sarva-bhūta-ātma-bhūta-ātmā—one who sees the Soul of all souls in every living being; kurvan—performing; api—although; na—never; lipyate—entangled'),
('12b34c1a-6b73-5d37-9344-a19d3850f08a'::uuid, 5, 8, 212, 212, 'नैव किंचित्करोमीति युक्तो मन्येत तत्त्ववित्।

पश्यन् श्रृणवन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपन् श्वसन्।।5.8।।', 'naiva kiñchit karomīti yukto manyeta tattva-vit
paśhyañ śhṛiṇvan spṛiśhañjighrann aśhnangachchhan svapañśhvasan
 pralapan visṛijan gṛihṇann unmiṣhan nimiṣhann api
indriyāṇīndriyārtheṣhu vartanta iti dhārayan', '[{"word":"na","meaning":"not"},{"word":"eva","meaning":"certainly"},{"word":"kiñchit","meaning":"anything"},{"word":"karomi","meaning":"I do"},{"word":"iti","meaning":"thus"},{"word":"yuktaḥ","meaning":"steadfast in karm yog"},{"word":"manyeta","meaning":"thinks"},{"word":"tattva","meaning":"vit—one who knows the truth"},{"word":"paśhyan","meaning":"seeing"},{"word":"śhṛiṇvan","meaning":"hearing"},{"word":"spṛiśhan","meaning":"touching"},{"word":"jighran","meaning":"smelling"},{"word":"aśhnan","meaning":"eating"},{"word":"gachchhan","meaning":"moving"},{"word":"svapan","meaning":"sleeping"},{"word":"śhvasan","meaning":"breathing"},{"word":"pralapan","meaning":"talking"},{"word":"visṛijan","meaning":"giving up"},{"word":"gṛihṇan","meaning":"accepting"},{"word":"unmiṣhan","meaning":"opening (the eyes)"},{"word":"nimiṣhan","meaning":"closing (the eyes)"},{"word":"api","meaning":"although"},{"word":"indriyāṇi","meaning":"the senses"},{"word":"indriya","meaning":"artheṣhu—in sense-objects"},{"word":"vartante","meaning":"moving"},{"word":"iti","meaning":"thus"},{"word":"dhārayan","meaning":"convinced"}]'::jsonb, 'na—not; eva—certainly; kiñchit—anything; karomi—I do; iti—thus; yuktaḥ—steadfast in karm yog; manyeta—thinks; tattva-vit—one who knows the truth; paśhyan—seeing; śhṛiṇvan—hearing; spṛiśhan—touching; jighran—smelling; aśhnan—eating; gachchhan—moving; svapan—sleeping; śhvasan—breathing;
 pralapan—talking; visṛijan—giving up; gṛihṇan—accepting; unmiṣhan—opening (the eyes); nimiṣhan—closing (the eyes); api—although; indriyāṇi—the senses; indriya-artheṣhu—in sense-objects; vartante—moving; iti—thus; dhārayan—convinced'),
('73bffac7-e17a-57aa-860d-7c08511d7b0c'::uuid, 5, 9, 213, 213, 'प्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि।

इन्द्रियाणीन्द्रियार्थेषु वर्तन्त इति धारयन्।।5.9।।', 'pralapan visṛjan gṛhṇann unmiṣan nimiṣann api indriyāṇīndriyārtheṣu vartanta iti dhārayan', '[{"word":"pralapan","meaning":"by talking"},{"word":"visṛjan","meaning":"by giving up"},{"word":"gṛhṇan","meaning":"by accepting"},{"word":"unmiṣan","meaning":"opening"},{"word":"nimiṣan","meaning":"closing"},{"word":"api","meaning":"in spite of"},{"word":"indriyāṇi","meaning":"the senses"},{"word":"indriya","meaning":"artheṣu—in sense gratification"},{"word":"vartante","meaning":"let    them be so engaged"},{"word":"iti","meaning":"thus"},{"word":"dhārayan","meaning":"considering."}]'::jsonb, 'pralapan—by talking; visṛjan—by giving up; gṛhṇan—by accepting; unmiṣan—opening; nimiṣan—closing; api—in spite of; indriyāṇi—the senses; indriya-artheṣu—in sense gratification;   vartante—let    them be so engaged; iti—thus;   dhārayan—considering.'),
('9673c10a-f5d5-5191-9c94-5966c2bb7e43'::uuid, 5, 10, 214, 214, 'ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः।

लिप्यते न स पापेन पद्मपत्रमिवाम्भसा।।5.10।।', 'brahmaṇyādhāya karmāṇi saṅgaṁ tyaktvā karoti yaḥ
lipyate na sa pāpena padma-patram ivāmbhasā', '[{"word":"brahmaṇi","meaning":"to God"},{"word":"ādhāya","meaning":"dedicating"},{"word":"karmāṇi","meaning":"all actions"},{"word":"saṅgam","meaning":"attachment"},{"word":"tyaktvā","meaning":"abandoning"},{"word":"karoti","meaning":"performs"},{"word":"yaḥ","meaning":"who"},{"word":"lipyate","meaning":"is affected"},{"word":"na","meaning":"never"},{"word":"saḥ","meaning":"that person"},{"word":"pāpena","meaning":"by sin"},{"word":"padma","meaning":"patram—a lotus leaf"},{"word":"iva","meaning":"like"},{"word":"ambhasā","meaning":"by water"}]'::jsonb, 'brahmaṇi—to God; ādhāya—dedicating; karmāṇi—all actions; saṅgam—attachment; tyaktvā—abandoning; karoti—performs; yaḥ—who; lipyate—is affected; na—never; saḥ—that person; pāpena—by sin; padma-patram—a lotus leaf; iva—like; ambhasā—by water'),
('74bd969b-e672-5bd7-b84d-3011028aa3e1'::uuid, 5, 11, 215, 215, 'कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि।

योगिनः कर्म कुर्वन्ति सङ्गं त्यक्त्वाऽऽत्मशुद्धये।।5.11।।', 'kāyena manasā buddhyā kevalair indriyair api
yoginaḥ karma kurvanti saṅgaṁ tyaktvātma-śhuddhaye', '[{"word":"kāyena","meaning":"with the body"},{"word":"manasā","meaning":"with the mind"},{"word":"buddhyā","meaning":"with the intellect"},{"word":"kevalaiḥ","meaning":"only"},{"word":"indriyaiḥ","meaning":"with the senses"},{"word":"api","meaning":"even"},{"word":"yoginaḥ","meaning":"the yogis"},{"word":"karma","meaning":"actions"},{"word":"kurvanti","meaning":"perform"},{"word":"saṅgam","meaning":"attachment"},{"word":"tyaktvā","meaning":"giving up"},{"word":"ātma","meaning":"of the self"},{"word":"śhuddhaye","meaning":"for the purification"}]'::jsonb, 'kāyena—with the body; manasā—with the mind; buddhyā—with the intellect; kevalaiḥ—only; indriyaiḥ—with the senses; api—even; yoginaḥ—the yogis; karma—actions; kurvanti—perform; saṅgam—attachment; tyaktvā—giving up; ātma—of the self; śhuddhaye—for the purification'),
('aeecaaad-b559-5646-a1d3-223424f083c4'::uuid, 5, 12, 216, 216, 'युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम्।

अयुक्तः कामकारेण फले सक्तो निबध्यते।।5.12।।', 'yuktaḥ karma-phalaṁ tyaktvā śhāntim āpnoti naiṣhṭhikīm
ayuktaḥ kāma-kāreṇa phale sakto nibadhyate', '[{"word":"yuktaḥ","meaning":"one who is united in consciousness with God"},{"word":"karma","meaning":"phalam—the results of all activities"},{"word":"tyaktvā","meaning":"giving up"},{"word":"śhāntim","meaning":"peace"},{"word":"āpnoti","meaning":"attains"},{"word":"naiṣhṭhikīm","meaning":"everlasting"},{"word":"ayuktaḥ","meaning":"one who is not united with God in consciousness"},{"word":"kāma","meaning":"kāreṇa—impelled by desires"},{"word":"phale","meaning":"in the result"},{"word":"saktaḥ","meaning":"attached"},{"word":"nibadhyate","meaning":"becomes entangled"}]'::jsonb, 'yuktaḥ—one who is united in consciousness with God; karma-phalam—the results of all activities; tyaktvā—giving up; śhāntim—peace; āpnoti—attains; naiṣhṭhikīm—everlasting; ayuktaḥ—one who is not united with God in consciousness; kāma-kāreṇa—impelled by desires; phale—in the result; saktaḥ—attached; nibadhyate—becomes entangled'),
('e18dcd79-638e-5289-a871-cd53654cfd82'::uuid, 5, 13, 217, 217, 'सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी।

नवद्वारे पुरे देही नैव कुर्वन्न कारयन्।।5.13।।', 'sarva-karmāṇi manasā sannyasyāste sukhaṁ vaśhī
nava-dvāre pure dehī naiva kurvan na kārayan', '[{"word":"sarva","meaning":"all"},{"word":"karmāṇi","meaning":"activities"},{"word":"manasā","meaning":"by the mind"},{"word":"sannyasya","meaning":"having renounced"},{"word":"āste","meaning":"remains"},{"word":"sukham","meaning":"happily"},{"word":"vaśhī","meaning":"the self-controlled"},{"word":"nava","meaning":"dvāre—of nine gates"},{"word":"pure","meaning":"in the city"},{"word":"dehī","meaning":"the embodied being"},{"word":"na","meaning":"never"},{"word":"eva","meaning":"certainly"},{"word":"kurvan","meaning":"doing anything"},{"word":"na","meaning":"not"},{"word":"kārayan","meaning":"causing to be done"}]'::jsonb, 'sarva—all; karmāṇi—activities; manasā—by the mind; sannyasya—having renounced; āste—remains; sukham—happily; vaśhī—the self-controlled; nava-dvāre—of nine gates; pure—in the city; dehī—the embodied being; na—never; eva—certainly; kurvan—doing anything; na—not; kārayan—causing to be done'),
('a0cd9f97-0972-5fd6-8e4b-08c0b8bfe688'::uuid, 5, 14, 218, 218, 'न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः।

न कर्मफलसंयोगं स्वभावस्तु प्रवर्तते।।5.14।।', 'na kartṛitvaṁ na karmāṇi lokasya sṛijati prabhuḥ
na karma-phala-saṅyogaṁ svabhāvas tu pravartate', '[{"word":"na","meaning":"neither"},{"word":"kartṛitvam","meaning":"sense of doership"},{"word":"na","meaning":"nor"},{"word":"karmāṇi","meaning":"actions"},{"word":"lokasya","meaning":"of the people"},{"word":"sṛijati","meaning":"creates"},{"word":"prabhuḥ","meaning":"God"},{"word":"na","meaning":"nor"},{"word":"karma","meaning":"phala—fruits of actions"},{"word":"sanyogam","meaning":"connection"},{"word":"svabhāvaḥ","meaning":"one’s nature"},{"word":"tu","meaning":"but"},{"word":"pravartate","meaning":"is enacted"}]'::jsonb, 'na—neither; kartṛitvam—sense of doership; na—nor; karmāṇi—actions; lokasya—of the people; sṛijati—creates; prabhuḥ—God; na—nor; karma-phala—fruits of actions; sanyogam—connection; svabhāvaḥ—one’s nature; tu—but; pravartate—is enacted'),
('b1c614d1-62aa-56e0-a81a-49b8b7e9f6ab'::uuid, 5, 15, 219, 219, 'नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः।

अज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः।।5.15।।', 'nādatte kasyachit pāpaṁ na chaiva sukṛitaṁ vibhuḥ
ajñānenāvṛitaṁ jñānaṁ tena muhyanti jantavaḥ', '[{"word":"na","meaning":"not"},{"word":"ādatte","meaning":"accepts"},{"word":"kasyachit","meaning":"anyone’s"},{"word":"pāpam","meaning":"sin"},{"word":"na","meaning":"not"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"certainly"},{"word":"su","meaning":"kṛitam—virtuous deeds"},{"word":"vibhuḥ","meaning":"the omnipresent God"},{"word":"ajñānena","meaning":"by ignorance"},{"word":"āvṛitam","meaning":"covered"},{"word":"jñānam","meaning":"knowledge"},{"word":"tena","meaning":"by that"},{"word":"muhyanti","meaning":"are deluded"},{"word":"jantavaḥ","meaning":"the living entities"}]'::jsonb, 'na—not; ādatte—accepts; kasyachit—anyone’s; pāpam—sin; na—not; cha—and; eva—certainly; su-kṛitam—virtuous deeds; vibhuḥ—the omnipresent God; ajñānena—by ignorance; āvṛitam—covered; jñānam—knowledge; tena—by that; muhyanti—are deluded; jantavaḥ—the living entities'),
('c43cb171-1e2c-54ae-b567-5f768543c49c'::uuid, 5, 16, 220, 220, 'ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः।

तेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम्।।5.16।।', 'jñānena tu tad ajñānaṁ yeṣhāṁ nāśhitam ātmanaḥ
teṣhām āditya-vaj jñānaṁ prakāśhayati tat param', '[{"word":"jñānena","meaning":"by divine knowledge"},{"word":"tu","meaning":"but"},{"word":"tat","meaning":"that"},{"word":"ajñānam","meaning":"ignorance"},{"word":"yeṣhām","meaning":"whose"},{"word":"nāśhitam","meaning":"has been destroyed"},{"word":"ātmanaḥ","meaning":"of the self"},{"word":"teṣhām","meaning":"their"},{"word":"āditya","meaning":"vat—like the sun"},{"word":"jñānam","meaning":"knowledge"},{"word":"prakāśhayati","meaning":"illumines"},{"word":"tat","meaning":"that"},{"word":"param","meaning":"Supreme Entity"}]'::jsonb, 'jñānena—by divine knowledge; tu—but; tat—that; ajñānam—ignorance; yeṣhām—whose; nāśhitam—has been destroyed; ātmanaḥ—of the self; teṣhām—their; āditya-vat—like the sun; jñānam—knowledge; prakāśhayati—illumines; tat—that; param—Supreme Entity'),
('81460644-56a1-55ec-a4c7-1ef46e137b3c'::uuid, 5, 17, 221, 221, 'तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः।

गच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः।।5.17।।', 'tad-buddhayas tad-ātmānas tan-niṣhṭhās tat-parāyaṇāḥ
gachchhantyapunar-āvṛittiṁ jñāna-nirdhūta-kalmaṣhāḥ', '[{"word":"tat","meaning":"buddhayaḥ—those whose intellect is directed toward God"},{"word":"tat","meaning":"ātmānaḥ—those whose heart (mind and intellect) is solely absorbed in God"},{"word":"tat","meaning":"niṣhṭhāḥ—those whose intellect has firm faith in God"},{"word":"tat","meaning":"parāyaṇāḥ—those who strive after God as the supreme goal and refuge"},{"word":"gachchhanti","meaning":"go"},{"word":"apunaḥ","meaning":"āvṛittim—not returning"},{"word":"jñāna","meaning":"by knowledge"},{"word":"nirdhūta","meaning":"dispelled"},{"word":"kalmaṣhāḥ","meaning":"sins"}]'::jsonb, 'tat-buddhayaḥ—those whose intellect is directed toward God; tat-ātmānaḥ—those whose heart (mind and intellect) is solely absorbed in God; tat-niṣhṭhāḥ—those whose intellect has firm faith in God; tat-parāyaṇāḥ—those who strive after God as the supreme goal and refuge; gachchhanti—go; apunaḥ-āvṛittim—not returning; jñāna—by knowledge; nirdhūta—dispelled; kalmaṣhāḥ—sins'),
('60d4f4f7-0f08-51e9-8c73-206e7ea48bfe'::uuid, 5, 18, 222, 222, 'विद्याविनयसंपन्ने ब्राह्मणे गवि हस्तिनि।

शुनि चैव श्वपाके च पण्डिताः समदर्शिनः।।5.18।।', 'vidyā-vinaya-sampanne brāhmaṇe gavi hastini
śhuni chaiva śhva-pāke cha paṇḍitāḥ sama-darśhinaḥ', '[{"word":"vidyā","meaning":"divine knowledge"},{"word":"vinaya","meaning":"humbleness"},{"word":"sampanne","meaning":"equipped with"},{"word":"brāhmaṇe","meaning":"a Brahmin"},{"word":"gavi","meaning":"a cow"},{"word":"hastini","meaning":"an elephant"},{"word":"śhuni","meaning":"a dog"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"certainly"},{"word":"śhva","meaning":"pāke—a dog-eater"},{"word":"cha","meaning":"and"},{"word":"paṇḍitāḥ","meaning":"the learned"},{"word":"sama","meaning":"darśhinaḥ—see with equal vision"}]'::jsonb, 'vidyā—divine knowledge; vinaya—humbleness; sampanne—equipped with; brāhmaṇe—a Brahmin; gavi—a cow; hastini—an elephant; śhuni—a dog; cha—and; eva—certainly; śhva-pāke—a dog-eater; cha—and; paṇḍitāḥ—the learned; sama-darśhinaḥ—see with equal vision'),
('c55d2e32-cfa3-508e-b624-eb3adea5d69f'::uuid, 5, 19, 223, 223, 'इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः।

निर्दोषं हि समं ब्रह्म तस्माद्ब्रह्मणि ते स्थिताः।।5.19।।', 'ihaiva tair jitaḥ sargo yeṣhāṁ sāmye sthitaṁ manaḥ
nirdoṣhaṁ hi samaṁ brahma tasmād brahmaṇi te sthitāḥ', '[{"word":"iha eva","meaning":"in this very life"},{"word":"taiḥ","meaning":"by them"},{"word":"jitaḥ","meaning":"conquer"},{"word":"sargaḥ","meaning":"the creation"},{"word":"yeṣhām","meaning":"whose"},{"word":"sāmye","meaning":"in equanimity"},{"word":"sthitam","meaning":"situated"},{"word":"manaḥ","meaning":"mind"},{"word":"nirdoṣham","meaning":"flawless"},{"word":"hi","meaning":"certainly"},{"word":"samam","meaning":"in equality"},{"word":"brahma","meaning":"God"},{"word":"tasmāt","meaning":"therefore"},{"word":"brahmaṇi","meaning":"in the Absolute Truth"},{"word":"te","meaning":"they"},{"word":"sthitāḥ","meaning":"are seated"}]'::jsonb, 'iha eva—in this very life; taiḥ—by them; jitaḥ—conquer; sargaḥ—the creation; yeṣhām—whose; sāmye—in equanimity; sthitam—situated; manaḥ—mind; nirdoṣham—flawless; hi—certainly; samam—in equality; brahma—God; tasmāt—therefore; brahmaṇi—in the Absolute Truth; te—they; sthitāḥ—are seated'),
('11d5bf6f-c012-5737-84fe-adadfc2a9841'::uuid, 5, 20, 224, 224, 'न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम्।

स्थिरबुद्धिरसम्मूढो ब्रह्मविद्ब्रह्मणि स्थितः।।5.20।।', 'na prahṛiṣhyet priyaṁ prāpya nodvijet prāpya chāpriyam
sthira-buddhir asammūḍho brahma-vid brahmaṇi sthitaḥ', '[{"word":"na","meaning":"neither"},{"word":"prahṛiṣhyet","meaning":"rejoice"},{"word":"priyam","meaning":"the pleasant"},{"word":"prāpya","meaning":"obtaining"},{"word":"na","meaning":"nor"},{"word":"udvijet","meaning":"become disturbed"},{"word":"prāpya","meaning":"attaining"},{"word":"cha","meaning":"also"},{"word":"apriyam","meaning":"the unpleasant"},{"word":"sthira","meaning":"buddhiḥ—steady intellect"},{"word":"asammūḍhaḥ","meaning":"firmly situated"},{"word":"brahma","meaning":"vit—having a firm understanding of divine knowledge"},{"word":"brahmaṇi","meaning":"established in God"},{"word":"sthitaḥ","meaning":"situated"}]'::jsonb, 'na—neither; prahṛiṣhyet—rejoice; priyam—the pleasant; prāpya—obtaining; na—nor; udvijet—become disturbed; prāpya—attaining; cha—also; apriyam—the unpleasant; sthira-buddhiḥ—steady intellect; asammūḍhaḥ—firmly situated; brahma-vit—having a firm understanding of divine knowledge; brahmaṇi—established in God; sthitaḥ—situated'),
('31b4cea4-4406-5adc-8790-6fd1e215b3d7'::uuid, 5, 21, 225, 225, 'बाह्यस्पर्शेष्वसक्तात्मा विन्दत्यात्मनि यत्सुखम्।

स ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते।।5.21।।', 'bāhya-sparśheṣhvasaktātmā vindatyātmani yat sukham
sa brahma-yoga-yuktātmā sukham akṣhayam aśhnute', '[{"word":"bāhya","meaning":"sparśheṣhu—external sense pleasure"},{"word":"asakta","meaning":"ātmā—those who are unattached"},{"word":"vindati","meaning":"find"},{"word":"ātmani","meaning":"in the self"},{"word":"yat","meaning":"which"},{"word":"sukham","meaning":"bliss"},{"word":"saḥ","meaning":"that person"},{"word":"brahma","meaning":"yoga yukta-ātmā—those who are united with God through yog"},{"word":"sukham","meaning":"happiness"},{"word":"akṣhayam","meaning":"unlimited"},{"word":"aśhnute","meaning":"experiences"}]'::jsonb, 'bāhya-sparśheṣhu—external sense pleasure; asakta-ātmā—those who are unattached; vindati—find; ātmani—in the self; yat—which; sukham—bliss; saḥ—that person; brahma-yoga yukta-ātmā—those who are united with God through yog; sukham—happiness; akṣhayam—unlimited; aśhnute—experiences'),
('529b2022-6c47-5fa1-a58e-0cf3882b509d'::uuid, 5, 22, 226, 226, 'ये हि संस्पर्शजा भोगा दुःखयोनय एव ते।

आद्यन्तवन्तः कौन्तेय न तेषु रमते बुधः।।5.22।।', 'ye hi sansparśha-jā bhogā duḥkha-yonaya eva te
ādyantavantaḥ kaunteya na teṣhu ramate budhaḥ', '[{"word":"ye","meaning":"which"},{"word":"hi","meaning":"verily"},{"word":"sansparśha","meaning":"jāḥ—born of contact with the sense objects"},{"word":"bhogāḥ","meaning":"pleasures"},{"word":"duḥkha","meaning":"misery"},{"word":"yonayaḥ","meaning":"source of"},{"word":"eva","meaning":"verily"},{"word":"te","meaning":"they are"},{"word":"ādya","meaning":"antavantaḥ—having beginning and end"},{"word":"kaunteya","meaning":"Arjun, the son of Kunti"},{"word":"na","meaning":"never"},{"word":"teṣhu","meaning":"in those"},{"word":"ramate","meaning":"takes delight"},{"word":"budhaḥ","meaning":"the wise"}]'::jsonb, 'ye—which; hi—verily; sansparśha-jāḥ—born of contact with the sense objects; bhogāḥ—pleasures; duḥkha—misery; yonayaḥ—source of; eva—verily; te—they are; ādya-antavantaḥ—having beginning and end; kaunteya—Arjun, the son of Kunti; na—never; teṣhu—in those; ramate—takes delight; budhaḥ—the wise'),
('1f28dbbf-1d29-5042-bba7-93a4ac3bc8bc'::uuid, 5, 23, 227, 227, 'शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात्।

कामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः।।5.23।।', 'śhaknotīhaiva yaḥ soḍhuṁ prāk śharīra-vimokṣhaṇāt
kāma-krodhodbhavaṁ vegaṁ sa yuktaḥ sa sukhī naraḥ', '[{"word":"śhaknoti","meaning":"is able"},{"word":"iha eva","meaning":"in the present body"},{"word":"yaḥ","meaning":"who"},{"word":"soḍhum","meaning":"to withstand"},{"word":"prāk","meaning":"before"},{"word":"śharīra","meaning":"the body"},{"word":"vimokṣhaṇāt","meaning":"giving up"},{"word":"kāma","meaning":"desire"},{"word":"krodha","meaning":"anger"},{"word":"udbhavam","meaning":"generated from"},{"word":"vegam","meaning":"forces"},{"word":"saḥ","meaning":"that person"},{"word":"yuktaḥ","meaning":"yogi"},{"word":"saḥ","meaning":"that person"},{"word":"sukhī","meaning":"happy"},{"word":"naraḥ","meaning":"person"}]'::jsonb, 'śhaknoti—is able; iha eva—in the present body; yaḥ—who; soḍhum—to withstand; prāk—before; śharīra—the body; vimokṣhaṇāt—giving up; kāma—desire; krodha—anger; udbhavam—generated from; vegam—forces; saḥ—that person; yuktaḥ—yogi; saḥ—that person; sukhī—happy; naraḥ—person'),
('b710e44d-77bd-5428-9bc3-0a376e233f3c'::uuid, 5, 24, 228, 228, 'योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः।

