('b690b975-ea06-5027-b3af-7f6afbeba90f'::uuid, 6, 10, 243, 243, 'योगी युञ्जीत सततमात्मानं रहसि स्थितः।

एकाकी यतचित्तात्मा निराशीरपरिग्रहः।।6.10।।', 'yogī yuñjīta satatam ātmānaṁ rahasi sthitaḥ
ekākī yata-chittātmā nirāśhīr aparigrahaḥ', '[{"word":"yogī","meaning":"a yogi"},{"word":"yuñjīta","meaning":"should remain engaged in meditation"},{"word":"satatam","meaning":"constantly"},{"word":"ātmānam","meaning":"self"},{"word":"rahasi","meaning":"in seclusion"},{"word":"sthitaḥ","meaning":"remaining"},{"word":"ekākī","meaning":"alone"},{"word":"yata","meaning":"chitta-ātmā—with a controlled mind and body"},{"word":"nirāśhīḥ","meaning":"free from desires"},{"word":"aparigrahaḥ","meaning":"free from desires for possessions for enjoyment"}]'::jsonb, 'yogī—a yogi; yuñjīta—should remain engaged in meditation; satatam—constantly; ātmānam—self; rahasi—in seclusion; sthitaḥ—remaining; ekākī—alone; yata-chitta-ātmā—with a controlled mind and body; nirāśhīḥ—free from desires; aparigrahaḥ—free from desires for possessions for enjoyment'),
('4d9b3f97-da7a-5e71-a4d4-9d6263238e9f'::uuid, 6, 11, 244, 244, 'शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः।

नात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम्।।6.11।।', 'śhuchau deśhe pratiṣhṭhāpya sthiram āsanam ātmanaḥ
nātyuchchhritaṁ nāti-nīchaṁ chailājina-kuśhottaram', '[{"word":"śhuchau","meaning":"in a clean"},{"word":"deśhe","meaning":"place"},{"word":"pratiṣhṭhāpya","meaning":"having established"},{"word":"sthiram","meaning":"steadfast"},{"word":"āsanam","meaning":"seat"},{"word":"ātmanaḥ","meaning":"his own"},{"word":"na","meaning":"not"},{"word":"ati","meaning":"too"},{"word":"uchchhritam","meaning":"high"},{"word":"na","meaning":"not"},{"word":"ati","meaning":"too"},{"word":"nīcham","meaning":"low"},{"word":"chaila","meaning":"cloth"},{"word":"ajina","meaning":"a deerskin"},{"word":"kuśha","meaning":"kuśh grass"},{"word":"uttaram","meaning":"one over the other"}]'::jsonb, 'śhuchau—in a clean; deśhe—place; pratiṣhṭhāpya—having established; sthiram—steadfast; āsanam—seat; ātmanaḥ—his own; na—not; ati—too; uchchhritam—high; na—not; ati—too; nīcham—low; chaila—cloth; ajina—a deerskin; kuśha—kuśh grass; uttaram—one over the other'),
('ab1fa93d-b564-5961-9051-e807bdb7cdfe'::uuid, 6, 12, 245, 245, 'तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः।

उपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये।।6.12।।', 'tatraikāgraṁ manaḥ kṛitvā yata-chittendriya-kriyaḥ
upaviśhyāsane yuñjyād yogam ātma-viśhuddhaye', '[{"word":"tatra","meaning":"there"},{"word":"eka","meaning":"agram—one-pointed"},{"word":"manaḥ","meaning":"mind"},{"word":"kṛitvā","meaning":"having made"},{"word":"yata","meaning":"chitta—controlling the mind"},{"word":"indriya","meaning":"senses"},{"word":"kriyaḥ","meaning":"activities"},{"word":"upaviśhya","meaning":"being seated"},{"word":"āsane","meaning":"on the seat"},{"word":"yuñjyāt yogam","meaning":"should strive to practice yog"},{"word":"ātma viśhuddhaye","meaning":"for purification of the mind"}]'::jsonb, 'tatra—there; eka-agram—one-pointed; manaḥ—mind; kṛitvā—having made; yata-chitta—controlling the mind; indriya—senses; kriyaḥ—activities; upaviśhya—being seated; āsane—on the seat; yuñjyāt yogam—should strive to practice yog; ātma viśhuddhaye—for purification of the mind;'),
('8c40219d-a0c1-5019-8ab1-b65eb51e6af2'::uuid, 6, 13, 246, 246, 'समं कायशिरोग्रीवं धारयन्नचलं स्थिरः।

संप्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन्।।6.13।।', 'samaṁ kāya-śhiro-grīvaṁ dhārayann achalaṁ sthiraḥ
samprekṣhya nāsikāgraṁ svaṁ diśhaśh chānavalokayan', '[{"word":"samam","meaning":"straight"},{"word":"kāya","meaning":"body"},{"word":"śhiraḥ","meaning":"head"},{"word":"grīvam","meaning":"neck"},{"word":"dhārayan","meaning":"holding"},{"word":"achalam","meaning":"unmoving"},{"word":"sthiraḥ","meaning":"still"},{"word":"samprekṣhya","meaning":"gazing"},{"word":"nāsika","meaning":"agram—at the tip of the nose"},{"word":"svam","meaning":"own"},{"word":"diśhaḥ","meaning":"directions"},{"word":"cha","meaning":"and"},{"word":"anavalokayan","meaning":"not looking"}]'::jsonb, 'samam—straight; kāya—body; śhiraḥ—head; grīvam—neck; dhārayan—holding; achalam—unmoving; sthiraḥ—still; samprekṣhya—gazing; nāsika-agram—at the tip of the nose; svam—own; diśhaḥ—directions; cha—and; anavalokayan—not looking'),
('899b7c59-072f-54dc-afdf-66ae22c9f133'::uuid, 6, 14, 247, 247, 'प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः।

मनः संयम्य मच्चित्तो युक्त आसीत मत्परः।।6.14।।', 'praśhāntātmā vigata-bhīr brahmachāri-vrate sthitaḥ
manaḥ sanyamya mach-chitto yukta āsīta mat-paraḥ', '[{"word":"praśhānta","meaning":"serene"},{"word":"ātmā","meaning":"mind"},{"word":"vigata","meaning":"bhīḥ—fearless"},{"word":"brahmachāri","meaning":"vrate—in the vow of celibacy"},{"word":"sthitaḥ","meaning":"situated"},{"word":"manaḥ","meaning":"mind"},{"word":"sanyamya","meaning":"having controlled"},{"word":"mat","meaning":"chittaḥ—meditate on me (Shree Krishna)"},{"word":"yuktaḥ","meaning":"engaged"},{"word":"āsīta","meaning":"should sit"},{"word":"mat","meaning":"paraḥ—having me as the supreme goal"}]'::jsonb, 'praśhānta—serene; ātmā—mind; vigata-bhīḥ—fearless; brahmachāri-vrate—in the vow of celibacy; sthitaḥ—situated; manaḥ—mind; sanyamya—having controlled; mat-chittaḥ—meditate on me (Shree Krishna); yuktaḥ—engaged; āsīta—should sit; mat-paraḥ—having me as the supreme goal'),
('3f36ebe7-5494-5f14-8ec8-dfb10b391511'::uuid, 6, 15, 248, 248, 'युञ्जन्नेवं सदाऽऽत्मानं योगी नियतमानसः।

शान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति।।6.15।।', 'yuñjann evaṁ sadātmānaṁ yogī niyata-mānasaḥ
śhantiṁ nirvāṇa-paramāṁ mat-sansthām adhigachchhati', '[{"word":"yuñjan","meaning":"keeping the mind absorbed in God"},{"word":"evam","meaning":"thus"},{"word":"sadā","meaning":"constantly"},{"word":"ātmānam","meaning":"the mind"},{"word":"yogī","meaning":"a yogi"},{"word":"niyata","meaning":"mānasaḥ—one with a disciplined mind"},{"word":"śhāntim","meaning":"peace"},{"word":"nirvāṇa","meaning":"liberation from the material bondage"},{"word":"paramām","meaning":"supreme"},{"word":"mat","meaning":"sansthām—abides in me"},{"word":"adhigachchhati","meaning":"attains"}]'::jsonb, 'yuñjan—keeping the mind absorbed in God; evam—thus; sadā—constantly; ātmānam—the mind; yogī—a yogi; niyata-mānasaḥ—one with a disciplined mind; śhāntim—peace; nirvāṇa—liberation from the material bondage; paramām—supreme; mat-sansthām—abides in me; adhigachchhati—attains'),
('14a21db0-98ad-5fb8-87e2-03033a6b2ea7'::uuid, 6, 16, 249, 249, 'नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः।

न चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन।।6.16।।', 'nātyaśhnatastu yogo ’sti na chaikāntam anaśhnataḥ
na chāti-svapna-śhīlasya jāgrato naiva chārjuna', '[{"word":"na","meaning":"not"},{"word":"ati","meaning":"too much"},{"word":"aśhnataḥ","meaning":"of one who eats"},{"word":"tu","meaning":"however"},{"word":"yogaḥ","meaning":"Yog"},{"word":"asti","meaning":"there is"},{"word":"na","meaning":"not"},{"word":"cha","meaning":"and"},{"word":"ekāntam","meaning":"at all"},{"word":"anaśhnataḥ","meaning":"abstaining from eating"},{"word":"na","meaning":"not"},{"word":"cha","meaning":"and"},{"word":"ati","meaning":"too much"},{"word":"svapna","meaning":"śhīlasya—of one who sleeps"},{"word":"jāgrataḥ","meaning":"of one who does not sleep enough"},{"word":"na","meaning":"not"},{"word":"eva","meaning":"certainly"},{"word":"cha","meaning":"and"},{"word":"arjuna","meaning":"Arjun"}]'::jsonb, 'na—not; ati—too much; aśhnataḥ—of one who eats; tu—however; yogaḥ—Yog; asti—there is; na—not; cha—and; ekāntam—at all; anaśhnataḥ—abstaining from eating; na—not; cha—and; ati—too much; svapna-śhīlasya—of one who sleeps; jāgrataḥ—of one who does not sleep enough; na—not; eva—certainly; cha—and; arjuna—Arjun'),
('faf664c7-c7cf-5613-b51e-f61862db4266'::uuid, 6, 17, 250, 250, 'युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु।

युक्तस्वप्नावबोधस्य योगो भवति दुःखहा।।6.17।।', 'yuktāhāra-vihārasya yukta-cheṣhṭasya karmasu
yukta-svapnāvabodhasya yogo bhavati duḥkha-hā', '[{"word":"yukta","meaning":"moderate"},{"word":"āhāra","meaning":"eating"},{"word":"vihārasya","meaning":"recreation"},{"word":"yukta cheṣhṭasya karmasu","meaning":"balanced in work"},{"word":"yukta","meaning":"regulated"},{"word":"svapna","meaning":"avabodhasya—sleep and wakefulness"},{"word":"yogaḥ","meaning":"Yog"},{"word":"bhavati","meaning":"becomes"},{"word":"duḥkha","meaning":"hā—the slayer of sorrows"}]'::jsonb, 'yukta—moderate; āhāra—eating; vihārasya—recreation; yukta cheṣhṭasya karmasu—balanced in work; yukta—regulated; svapna-avabodhasya—sleep and wakefulness; yogaḥ—Yog; bhavati—becomes; duḥkha-hā—the slayer of sorrows'),
('fadb8f4a-df29-5233-96e7-0c092e197e20'::uuid, 6, 18, 251, 251, 'यदा विनियतं चित्तमात्मन्येवावतिष्ठते।

निःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा।।6.18।।', 'yadā viniyataṁ chittam ātmanyevāvatiṣhṭhate
niḥspṛihaḥ sarva-kāmebhyo yukta ityuchyate tadā', '[{"word":"yadā","meaning":"when"},{"word":"viniyatam","meaning":"fully controlled"},{"word":"chittam","meaning":"the mind"},{"word":"ātmani","meaning":"of the self"},{"word":"eva","meaning":"certainly"},{"word":"avatiṣhṭhate","meaning":"stays"},{"word":"nispṛihaḥ","meaning":"free from cravings: sarva"},{"word":"kāmebhyaḥ","meaning":"for yearning of the senses"},{"word":"yuktaḥ","meaning":"situated in perfect Yog"},{"word":"iti","meaning":"thus"},{"word":"uchyate","meaning":"is said"},{"word":"tadā","meaning":"then"}]'::jsonb, 'yadā—when; viniyatam—fully controlled; chittam—the mind; ātmani—of the self; eva—certainly; avatiṣhṭhate—stays; nispṛihaḥ—free from cravings: sarva; kāmebhyaḥ—for yearning of the senses; yuktaḥ—situated in perfect Yog; iti—thus; uchyate—is said; tadā—then'),
('1d61291d-21ea-5ba9-a2f8-9436b7990adc'::uuid, 6, 19, 252, 252, 'यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता।

योगिनो यतचित्तस्य युञ्जतो योगमात्मनः।।6.19।।', 'yathā dīpo nivāta-stho neṅgate sopamā smṛitā
yogino yata-chittasya yuñjato yogam ātmanaḥ', '[{"word":"yathā","meaning":"as"},{"word":"dīpaḥ","meaning":"a lamp"},{"word":"nivāta","meaning":"sthaḥ—in a windless place"},{"word":"na","meaning":"does not"},{"word":"iṅgate","meaning":"flickers"},{"word":"sā","meaning":"this"},{"word":"upamā","meaning":"analogy"},{"word":"smṛitā","meaning":"is considered"},{"word":"yoginaḥ","meaning":"of a yogi"},{"word":"yata","meaning":"chittasya—whose mind is disciplined"},{"word":"yuñjataḥ","meaning":"steadily practicing"},{"word":"yogam","meaning":"in meditation"},{"word":"ātmanaḥ","meaning":"on the Supreme"}]'::jsonb, 'yathā—as; dīpaḥ—a lamp; nivāta-sthaḥ—in a windless place; na—does not; iṅgate—flickers; sā—this; upamā—analogy; smṛitā—is considered; yoginaḥ—of a yogi; yata-chittasya—whose mind is disciplined; yuñjataḥ—steadily practicing; yogam—in meditation; ātmanaḥ—on the Supreme'),
('4883b50b-39dc-59ad-833f-71d2f1ce68e7'::uuid, 6, 20, 253, 253, 'यत्रोपरमते चित्तं निरुद्धं योगसेवया।

यत्र चैवात्मनाऽऽत्मानं पश्यन्नात्मनि तुष्यति।।6.20।।', 'yatroparamate chittaṁ niruddhaṁ yoga-sevayā
yatra chaivātmanātmānaṁ paśhyann ātmani tuṣhyati', '[{"word":"yatra","meaning":"when"},{"word":"uparamate","meaning":"rejoice inner joy"},{"word":"chittam","meaning":"the mind"},{"word":"niruddham","meaning":"restrained"},{"word":"yoga","meaning":"sevayā—by the practice of yog"},{"word":"yatra","meaning":"when"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"certainly"},{"word":"ātmanā","meaning":"through the purified mind"},{"word":"ātmānam","meaning":"the soul"},{"word":"paśhyan","meaning":"behold"},{"word":"ātmani","meaning":"in the self"},{"word":"tuṣhyati","meaning":"is satisfied"}]'::jsonb, 'yatra—when; uparamate—rejoice inner joy; chittam—the mind; niruddham—restrained; yoga-sevayā—by the practice of yog; yatra—when; cha—and; eva—certainly; ātmanā—through the purified mind; ātmānam—the soul; paśhyan—behold; ātmani—in the self; tuṣhyati—is satisfied'),
('fa6207f9-73d7-5fd2-b9c5-eee887d9169a'::uuid, 6, 21, 254, 254, 'सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम्।

वेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः।।6.21।।', 'sukham ātyantikaṁ yat tad buddhi-grāhyam atīndriyam
vetti yatra na chaivāyaṁ sthitaśh chalati tattvataḥ', '[{"word":"sukham","meaning":"happiness"},{"word":"ātyantikam","meaning":"limitless"},{"word":"yat","meaning":"which"},{"word":"tat","meaning":"that"},{"word":"buddhi","meaning":"by intellect"},{"word":"grāhyam","meaning":"grasp"},{"word":"atīndriyam","meaning":"transcending the senses"},{"word":"vetti","meaning":"knows"},{"word":"yatra","meaning":"wherein"},{"word":"na","meaning":"never"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"certainly"},{"word":"ayam","meaning":"he"},{"word":"sthitaḥ","meaning":"situated"},{"word":"chalati","meaning":"deviates"},{"word":"tattvataḥ","meaning":"from the Eternal Truth"}]'::jsonb, 'sukham—happiness; ātyantikam—limitless; yat—which; tat—that; buddhi—by intellect; grāhyam—grasp; atīndriyam—transcending the senses; vetti—knows; yatra—wherein; na—never; cha—and; eva—certainly; ayam—he; sthitaḥ—situated; chalati—deviates; tattvataḥ—from the Eternal Truth'),
('c71e647a-a852-5f28-a03f-18af441e86e9'::uuid, 6, 22, 255, 255, 'यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः।

यस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते।।6.22।।', 'yaṁ labdhvā chāparaṁ lābhaṁ manyate nādhikaṁ tataḥ
yasmin sthito na duḥkhena guruṇāpi vichālyate', '[{"word":"yam","meaning":"which"},{"word":"labdhvā","meaning":"having gained"},{"word":"cha","meaning":"and"},{"word":"aparam","meaning":"any other"},{"word":"lābham","meaning":"gain"},{"word":"manyate","meaning":"considers"},{"word":"na","meaning":"not"},{"word":"adhikam","meaning":"greater"},{"word":"tataḥ","meaning":"than that"},{"word":"yasmin","meaning":"in which"},{"word":"sthitaḥ","meaning":"being situated"},{"word":"na","meaning":"never"},{"word":"duḥkhena","meaning":"by sorrow"},{"word":"guruṇā","meaning":"(by) the greatest"},{"word":"api","meaning":"even"},{"word":"vichālyate","meaning":"is shaken"}]'::jsonb, 'yam—which; labdhvā—having gained; cha—and; aparam—any other; lābham—gain; manyate—considers; na—not; adhikam—greater; tataḥ—than that; yasmin—in which; sthitaḥ—being situated; na—never; duḥkhena—by sorrow; guruṇā—(by) the greatest; api—even; vichālyate—is shaken'),
('d9c58c9f-f181-5d83-8f21-6b1498f7085d'::uuid, 6, 23, 256, 256, 'तं विद्याद् दुःखसंयोगवियोगं योगसंज्ञितम्।

स निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा।।6.23।।', 'taṁ vidyād duḥkha-sanyoga-viyogaṁ yogasaṅjñitam
sa niśhchayena yoktavyo yogo ’nirviṇṇa-chetasā', '[{"word":"tam","meaning":"that"},{"word":"vidyāt","meaning":"you should know"},{"word":"duḥkha","meaning":"sanyoga-viyogam—state of severance from union with misery"},{"word":"yoga","meaning":"saṁjñitam—is known as yog"},{"word":"saḥ","meaning":"that"},{"word":"niśhchayena","meaning":"resolutely"},{"word":"yoktavyaḥ","meaning":"should be practiced"},{"word":"yogaḥ","meaning":"yog"},{"word":"anirviṇṇa","meaning":"chetasā—with an undeviating mind"}]'::jsonb, 'tam—that; vidyāt—you should know; duḥkha-sanyoga-viyogam—state of severance from union with misery; yoga-saṁjñitam—is known as yog; saḥ—that; niśhchayena—resolutely; yoktavyaḥ—should be practiced; yogaḥ—yog; anirviṇṇa-chetasā—with an undeviating mind'),
('87bc1125-fd57-58c5-a004-530fe0cafd4f'::uuid, 6, 24, 257, 257, 'सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः।

मनसैवेन्द्रियग्रामं विनियम्य समन्ततः।।6.24।।', 'saṅkalpa-prabhavān kāmāns tyaktvā sarvān aśheṣhataḥ
manasaivendriya-grāmaṁ viniyamya samantataḥ', '[{"word":"saṅkalpa","meaning":"a resolve"},{"word":"prabhavān","meaning":"born of"},{"word":"kāmān","meaning":"desires"},{"word":"tyaktvā","meaning":"having abandoned"},{"word":"sarvān","meaning":"all"},{"word":"aśheṣhataḥ","meaning":"completely"},{"word":"manasā","meaning":"through the mind"},{"word":"eva","meaning":"certainly"},{"word":"indriya","meaning":"grāmam—the group of senses"},{"word":"viniyamya","meaning":"restraining"},{"word":"samantataḥ","meaning":"from all sides"}]'::jsonb, 'saṅkalpa—a resolve; prabhavān—born of; kāmān—desires; tyaktvā—having abandoned; sarvān—all; aśheṣhataḥ—completely; manasā—through the mind; eva—certainly; indriya-grāmam—the group of senses; viniyamya—restraining; samantataḥ—from all sides;'),
('27a37edb-8993-5c61-9dbd-dfe32eee5327'::uuid, 6, 25, 258, 258, 'शनैः शनैरुपरमेद् बुद्ध्या धृतिगृहीतया।

आत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत्।।6.25।।', 'śhanaiḥ śhanair uparamed buddhyā dhṛiti-gṛihītayā
ātma-sansthaṁ manaḥ kṛitvā na kiñchid api chintayet', '[{"word":"śhanaiḥ","meaning":"gradually"},{"word":"śhanaiḥ","meaning":"gradually"},{"word":"uparamet","meaning":"attain peace"},{"word":"buddhyā","meaning":"by intellect"},{"word":"dhṛiti","meaning":"gṛihītayā—achieved through determination of resolve that is in accordance with scriptures"},{"word":"ātma","meaning":"sanstham—fixed in God"},{"word":"manaḥ","meaning":"mind"},{"word":"kṛitvā","meaning":"having made"},{"word":"na","meaning":"not"},{"word":"kiñchit","meaning":"anything"},{"word":"api","meaning":"even"},{"word":"chintayet","meaning":"should think of"}]'::jsonb, 'śhanaiḥ—gradually; śhanaiḥ—gradually; uparamet—attain peace; buddhyā—by intellect; dhṛiti-gṛihītayā—achieved through determination of resolve that is in accordance with scriptures; ātma-sanstham—fixed in God; manaḥ—mind; kṛitvā—having made; na—not; kiñchit—anything; api—even; chintayet—should think of'),
('fe5b1f4b-1bbf-5e74-b441-b0037176a6cf'::uuid, 6, 26, 259, 259, 'यतो यतो निश्चरति मनश्चञ्चलमस्थिरम्।

ततस्ततो नियम्यैतदात्मन्येव वशं नयेत्।।6.26।।', 'yato yato niśhcharati manaśh chañchalam asthiram
