('885a493f-d466-549b-9d95-13be09dc8f6a'::uuid, 9, 24, 362, 362, 'अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च।

न तु मामभिजानन्ति तत्त्वेनातश्च्यवन्ति ते।।9.24।।', 'ahaṁ hi sarva-yajñānāṁ bhoktā cha prabhureva cha
na tu mām abhijānanti tattvenātaśh chyavanti te', '[{"word":"aham","meaning":"I"},{"word":"hi","meaning":"verily"},{"word":"sarva","meaning":"of all"},{"word":"yajñānām","meaning":"sacrifices"},{"word":"bhoktā","meaning":"the enjoyer"},{"word":"cha","meaning":"and"},{"word":"prabhuḥ","meaning":"the Lord"},{"word":"eva","meaning":"only"},{"word":"cha","meaning":"and"},{"word":"na","meaning":"not"},{"word":"tu","meaning":"but"},{"word":"mām","meaning":"me"},{"word":"abhijānanti","meaning":"realize"},{"word":"tattvena","meaning":"divine nature"},{"word":"ataḥ","meaning":"therefore"},{"word":"chyavanti","meaning":"fall down (wander in samsara)"},{"word":"te","meaning":"they"}]'::jsonb, 'aham—I; hi—verily; sarva—of all; yajñānām—sacrifices; bhoktā—the enjoyer; cha—and; prabhuḥ—the Lord; eva—only; cha—and; na—not; tu—but; mām—me; abhijānanti—realize; tattvena—divine nature; ataḥ—therefore; chyavanti—fall down (wander in samsara); te—they'),
('6c482ef0-2212-57e6-a15c-73d2e50b963b'::uuid, 9, 25, 363, 363, 'यान्ति देवव्रता देवान् पितृ़न्यान्ति पितृव्रताः।

भूतानि यान्ति भूतेज्या यान्ति मद्याजिनोऽपि माम्।।9.25।।', 'yānti deva-vratā devān pitṝīn yānti pitṛi-vratāḥ
bhūtāni yānti bhūtejyā yānti mad-yājino ’pi mām', '[{"word":"yānti","meaning":"go"},{"word":"deva","meaning":"vratāḥ—worshipers of celestial gods"},{"word":"devān","meaning":"amongst the celestial gods"},{"word":"pitṝīn","meaning":"to the ancestors"},{"word":"yānti","meaning":"go"},{"word":"pitṛi","meaning":"vratā—worshippers of ancestors"},{"word":"bhūtāni","meaning":"to the ghosts"},{"word":"yānti","meaning":"go"},{"word":"bhūta","meaning":"ijyāḥ—worshippers of ghosts"},{"word":"yānti","meaning":"go"},{"word":"mat","meaning":"my"},{"word":"yājinaḥ","meaning":"devotees"},{"word":"api","meaning":"and"},{"word":"mām","meaning":"to me"}]'::jsonb, 'yānti—go; deva-vratāḥ—worshipers of celestial gods; devān—amongst the celestial gods; pitṝīn—to the ancestors; yānti—go; pitṛi-vratā—worshippers of ancestors; bhūtāni—to the ghosts; yānti—go; bhūta-ijyāḥ—worshippers of ghosts; yānti—go; mat—my; yājinaḥ—devotees; api—and; mām—to me'),
('98246330-d83a-5901-85db-65a623a260f0'::uuid, 9, 26, 364, 364, 'पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति।

तदहं भक्त्युपहृतमश्नामि प्रयतात्मनः।।9.26।।', 'patraṁ puṣhpaṁ phalaṁ toyaṁ yo me bhaktyā prayachchhati
